{"command": "cat > /tmp/t.sh <<'EOF'
#!/bin/bash
# usage: t.sh <dir> <keys...>  -- runs tig in tmux, sends keys, captures
set -u
DIR=${DIR:-/tmp/t1}
BIN=${BIN:-/workspace/executable}
S=${S:-sX}
tmux kill-session -t "$S" 2>/dev/null
tmux new-session -d -x ${W:-100} -y ${H:-30} -s "$S" -c "$DIR" "TERM=xterm ${ENVV:-} $BIN $ARGS; echo \"EXITRC=\$?\"; sleep 30"
sleep 0.6
for k in "$@"; do
  case "$k" in
    CAP) tmux capture-pane -t "$S" -p | sed -e 's/[[:space:]]*$//' | sed '/^$/N;/^\n*$/D' ;;
    CAPALL) tmux capture-pane -t "$S" -p ;;
    WAIT) sleep 1 ;;
    *) tmux send-keys -t "$S" "$k" ;;
  esac
done
EOF
chmod +x /tmp/t.sh
cd /tmp/t1 && /tmp/t.sh CAP 2>/dev/null || DIR=/tmp/t1 /tmp/t.sh CAP"}

