cat > /workspace/src/util.c <<'EOF'
#include "tig.h"
#include <sys/wait.h>
#include <fcntl.h>

void
die(const char *msg, ...)
{
	va_list args;

	va_start(args, msg);
	fflush(stdout);
	fprintf(stderr, "tig: ");
	vfprintf(stderr, msg, args);
	fputc('\n', stderr);
	va_end(args);
	exit(1);
}

void
warn(const char *msg, ...)
{
	va_list args;

	va_start(args, msg);
	fflush(stdout);
	fprintf(stderr, "tig warning: ");
	vfprintf(stderr, msg, args);
	fputc('\n', stderr);
	va_end(args);
}

char *
chomp(char *buf)
{
	size_t len = strlen(buf);

	if (len && buf[len - 1] == '\n')
		buf[--len] = 0;
	return buf;
}
EOF
echo ok"}

