const char *trace_file = NULL;
static FILE *trace_fp = NULL;

void
io_trace(const char *fmt, ...)
{
	va_list args;

	if (!trace_file)
		return;
	if (!trace_fp) {
		trace_fp = fopen(trace_file, "w");
		if (!trace_fp)
			return;
	}
	va_start(args, fmt);
	vfprintf(trace_fp, fmt, args);
	va_end(args);
	fflush(trace_fp);
}

static FILE *
open_trace_pipe(void)
{
	if (!trace_file)
		return NULL;
	if (!trace_fp) {
		trace_fp = fopen(trace_file, "w");
		if (!trace_fp)
			return NULL;
	}
	return trace_fp;
}

bool
io_open(struct io *io, const char *cmdfmt, ...)
{
	char cmd[SIZEOF_STR];
	va_list args;

	memset(io, 0, sizeof(*io));
	va_start(args, cmdfmt);
	vsnprintf(cmd, sizeof(cmd), cmdfmt, args);
	va_end(args);

	io_trace("%s \n", cmd);

