		FILE *err = open_trace_pipe();
		int devnull = -1;
		if (!err) {
			devnull = open("/dev/null", O_WRONLY);
		}
		fflush(stdout);
		fflush(stderr);
		io->pid = fork();
		if (io->pid == 0) {
			if (err) {
				dup2(fileno(err), 2);
