			execl("/bin/sh", "sh", "-c", cmd, (char *) NULL);
			_exit(127);
		}
		if (devnull >= 0)
			close(devnull);
	}
	if (io->pid == -1)
		return false;
	io->cmd = strdup(cmd);
	io->pipe = fdopen(io->pid ? -1 : -1, "r");
	return true;
}
