int
io_open(struct io *io, const char *cmdfmt, ...)
{
	char cmd[SIZEOF_STR];
	va_list args;
	int fds[2];
	pid_t pid;
	int devnull = -1;
	FILE *err;

	memset(io, 0, sizeof(*io));
	va_start(args, cmdfmt);
	vsnprintf(cmd, sizeof(cmd), cmdfmt, args);
	va_end(args);

	io_trace("%s \n", cmd);

	if (pipe(fds) < 0)
		return false;

	err = open_trace_pipe();
	if (!err)
		devnull = open("/dev/null", O_WRONLY);

	fflush(stdout);
	fflush(stderr);
	pid = fork();
	if (pid < 0) {
		close(fds[0]); close(fds[1]);
		if (devnull >= 0) close(devnull);
		return false;
	}
	if (pid == 0) {
		close(fds[0]);
		dup2(fds[1], 1);
		close(fds[1]);
		if (err)
			dup2(fileno(err), 2);
		else if (devnull >= 0) {
			dup2(devnull, 2);
		}
		execl("/bin/sh", "sh", "-c", cmd, (char *) NULL);
		_exit(127);
	}
	close(fds[1]);
	if (devnull >= 0)
		close(devnull);

	io->pipe = fdopen(fds[0], "r");
	io->pid = (int) pid;
	io->cmd = strdup(cmd);
	return true;
}

/* Read one record: up to '\n' or (in nulmode) up to '\0'. */
bool
io_get(struct io *io, char *buf, size_t size)
{
	size_t n = 0;
	int c;

	if (!io->pipe)
		return false;
	if (size == 0)
		return false;
	for (;;) {
		c = fgetc(io->pipe);
		if (c == EOF)
			break;
		if (io->nulmode && c == 0)
			break;
		if (!io->nulmode && c == '\n')
			break;
		if (n + 1 < size)
			buf[n++] = c;
		if (c == '\r' && !io->nulmode)
			;
	}
	buf[n] = 0;
	if (n == 0 && c == EOF)
		return false;
	return true;
}

