#include "io.h"

const char *trace_file = NULL;
static FILE *trace_fp = NULL;

void
io_trace(const char *fmt, ...)
{
	va_list args;

	if (!trace_file)
		return;
	if (!trace_fp) {
		trace_fp = fopen(trace_file, "w");
		if (!trace_fp)
			return;
	}
	va_start(args, fmt);
	vfprintf(trace_fp, fmt, args);
	va_end(args);
	fflush(trace_fp);
}

static FILE *
open_trace_pipe(void)
{
	if (!trace_file)
		return NULL;
	if (!trace_fp) {
		trace_fp = fopen(trace_file, "w");
		if (!trace_fp)
			return NULL;
	}
	return trace_fp;
}

bool
io_open(struct io *io, const char *cmdfmt, ...)
{
	char cmd[SIZEOF_STR];
	va_list args;
	int fds[2];
	pid_t pid;
	int devnull = -1;
	FILE *err;

	memset(io, 0, sizeof(*io));
	va_start(args, cmdfmt);
	vsnprintf(cmd, sizeof(cmd), cmdfmt, args);
	va_end(args);

	io_trace("%s \n", cmd);

	if (pipe(fds) < 0)
		return false;

	err = open_trace_pipe();
	if (!err)
		devnull = open("/dev/null", O_WRONLY);

	fflush(stdout);
	fflush(stderr);
	pid = fork();
	if (pid < 0) {
		close(fds[0]); close(fds[1]);
		if (devnull >= 0) close(devnull);
		return false;
	}
	if (pid == 0) {
		close(fds[0]);
		dup2(fds[1], 1);
		close(fds[1]);
		if (err)
			dup2(fileno(err), 2);
		else if (devnull >= 0) {
			dup2(devnull, 2);
		}
		execl("/bin/sh", "sh", "-c", cmd, (char *) NULL);
		_exit(127);
	}
	close(fds[1]);
	if (devnull >= 0)
		close(devnull);

	io->pipe = fdopen(fds[0], "r");
	io->pid = (int) pid;
	io->cmd = strdup(cmd);
	return true;
}

/* Read one record terminated by '\n' (or '\0' when nulmode is set). */
bool
io_get(struct io *io, char *buf, size_t size)
{
	size_t n = 0;
	int c = EOF;

	if (!io->pipe)
		return false;
	if (size == 0)
		return false;
	for (;;) {
		c = fgetc(io->pipe);
		if (c == EOF)
			break;
		if (c == (io->nulmode ? 0 : '\n'))
			break;
		if (n + 1 < size)
			buf[n++] = c;
	}
	buf[n] = 0;
	if (n == 0 && c == EOF)
		return false;
	return true;
}

void
io_done(struct io *io)
{
	int status = 0;

	if (!io->pipe)
		return;
	fclose(io->pipe);
	io->pipe = NULL;
	if (io->pid > 0) {
		while (waitpid(io->pid, &status, 0) < 0 && errno == EINTR)
			;
	}
	if (WIFEXITED(status))
		io->status = WEXITSTATUS(status);
	else if (WIFSIGNALED(status))
		io->status = WTERMSIG(status);
	else
		io->status = -1;
}

int
io_status(struct io *io)
{
	io_done(io);
	return io->status;
}

void
io_free(struct io *io)
{
	if (io->pipe) {
		fclose(io->pipe);
		io->pipe = NULL;
	}
	free((void *) io->cmd);
	io->cmd = NULL;
}

/* Run a command to completion, discarding stdout, return exit status. */
int
system_run(const char *cmdfmt, ...)
{
	char cmd[SIZEOF_STR];
	va_list args;
	int status;
	pid_t pid;
	FILE *err;
	int devnull = -1, fd;

	va_start(args, cmdfmt);
	vsnprintf(cmd, sizeof(cmd), cmdfmt, args);
	va_end(args);

	io_trace("%s \n", cmd);
	err = open_trace_pipe();
	if (!err)
		devnull = open("/dev/null", O_WRONLY);
	fflush(stdout);
	fflush(stderr);
	pid = fork();
	if (pid < 0) {
		if (devnull >= 0) close(devnull);
		return -1;
	}
	if (pid == 0) {
		fd = open("/dev/null", O_WRONLY);
		dup2(fd, 1);
		close(fd);
		if (err)
			dup2(fileno(err), 2);
		else if (devnull >= 0)
			dup2(devnull, 2);
		execl("/bin/sh", "sh", "-c", cmd, (char *) NULL);
		_exit(127);
	}
	if (devnull >= 0)
		close(devnull);
	while (waitpid(pid, &status, 0) < 0 && errno == EINTR)
		;
	return WIFEXITED(status) ? WEXITSTATUS(status) : -1;
}

/* Run a command capturing its full stdout into a buffer.  Returns true on
 * success (exit status 0). */
bool
capture_output(char *buf, size_t size, const char *cmdfmt, ...)
{
	char cmd[SIZEOF_STR];
	va_list args;
	struct io io;
	size_t n = 0;
	char line[SIZEOF_STR];

	memset(buf, 0, size);
	va_start(args, cmdfmt);
	vsnprintf(cmd, sizeof(cmd), cmdfmt, args);
	va_end(args);

	if (!io_open(&io, "%s", cmd))
		return false;
	while (io_get(&io, line, sizeof(line)) && n < size - 1) {
		size_t l = strlen(line);
		if (n + l + 2 > size)
			break;
		memcpy(buf + n, line, l);
		n += l;
		buf[n++] = '\n';
	}
	io_status(&io);
	io_free(&io);
	return io.status == 0;
}
EOF
echo ok"}

