color_from_name(const char *name, int *fg, int *bg, int *attr)
{
	*fg = -1; *bg = -1; *attr = 0;
	if (!strcasecmp(name, "default")) return 1;
	if (!strncasecmp(name, "color", 5) && isdigit((unsigned char) name[5])) {
		*fg = atoi(name + 5);
		return 1;
	}
	if (isdigit((unsigned char) name[0]) && !name[1]) {
		*fg = name[0] - '0';
		return 1;
	}
	if (!strcasecmp(name, "black")) { *fg = 0; return 1; }
	if (!strcasecmp(name, "red")) { *fg = 1; return 1; }
	if (!strcasecmp(name, "green")) { *fg = 2; return 1; }
	if (!strcasecmp(name, "yellow")) { *fg = 3; return 1; }
	if (!strcasecmp(name, "blue")) { *fg = 4; return 1; }
	if (!strcasecmp(name, "magenta")) { *fg = 5; return 1; }
	if (!strcasecmp(name, "cyan")) { *fg = 6; return 1; }
	if (!strcasecmp(name, "white")) { *fg = 7; return 1; }
	if (!strcasecmp(name, "normal")) { *fg = -1; return 1; }
	return 0;
}
