};

static struct option *
find_option(const char *name)
{
	unsigned i;

	for (i = 0; i < ARRAY_SIZE(options); i++)
		if (!strcasecmp(options[i].name, name))
			return &options[i];
	return NULL;
}

struct option *
option_get(const char *name)
{
	return find_option(name);
}

bool
parse_bool(const char *value, int *ival)
{
	if (!strcasecmp(value, "yes") || !strcasecmp(value, "true") ||
	    !strcasecmp(value, "on") || !strcmp(value, "1")) {
		*ival = 1;
		return true;
	}
	if (!strcasecmp(value, "no") || !strcasecmp(value, "false") ||
	    !strcasecmp(value, "off") || !strcmp(value, "0")) {
		*ival = 0;
		return true;
	}
	return false;
}

static bool
parse_pct(const char *value, int *ival)
{
	char *end;
	int n = (int) strtol(value, &end, 10);

	while (*end == ' ') end++;
	if (*end == '%') {
		*ival = n;
		return true;
	}
	if (!*end) {
		*ival = n;
		return true;
	}
	return false;
}

bool
option_set(const char *name, const char *value, bool quiet)
{
	struct option *o = find_option(name);
	int ival;

	if (!o) {
		/* view/column specific options are accepted silently */
		if (strstr(name, "view"))
			return true;
		if (!quiet)
			warn("%s: Unknown option name: %s", "?", name);
		return false;
	}
	switch (o->type) {
	case OPT_BOOL:
		if (!parse_bool(value, &ival)) {
			if (!quiet) warn("Invalid boolean value for %s: %s", name, value);
			return false;
		}
		o->ival = ival;
		sync_option(name, ival);
		break;
	case OPT_INT:
	case OPT_PCT:
		if (o->type == OPT_PCT || strchr(value, '%')) {
			if (!parse_pct(value, &ival)) {
				if (!quiet) warn("Invalid value for %s: %s", name, value);
				return false;
			}
		} else if (!strncasecmp(value, "0x", 2)) {
			ival = (int) strtol(value + 2, NULL, 16);
		} else {
			ival = atoi(value);
		}
		o->ival = ival;
		sync_option(name, ival);
		break;
	case OPT_ENUM:
		ival = enum_value(o->name, value);
		if (ival == -2) {
			if (!quiet) warn("Invalid value for %s: %s", name, value);
			return false;
		}
		o->ival = ival;
		sync_option(name, ival);
		break;
	case OPT_STRING:
		free(o->sval);
		o->sval = strdup(value);
		sync_option_str(name, o->sval);
		break;
	}
	return true;
}

static int
enum_value_for(const char *name, const char *value)
{
	if (!strcasecmp(name, "ignore-space")) {
		if (!strcasecmp(value, "no") || !strcasecmp(value, "false")) return 0;
		if (!strcasecmp(value, "all")) return 1;
		if (!strcasecmp(value, "some")) return 2;
		if (!strcasecmp(value, "at-eol")) return 3;
		return -2;
	}
	if (!strcasecmp(name, "commit-order")) {
		if (!strcasecmp(value, "auto")) return 0;
		if (!strcasecmp(value, "default")) return 1;
		if (!strcasecmp(value, "topo")) return 2;
		if (!strcasecmp(value, "date")) return 3;
		if (!strcasecmp(value, "author-date")) return 4;
		if (!strcasecmp(value, "reverse")) return 5;
		return -2;
	}
	if (!strcasecmp(name, "ignore-case")) {
		if (!strcasecmp(value, "no") || !strcasecmp(value, "false")) return 0;
		if (!strcasecmp(value, "yes") || !strcasecmp(value, "true")) return 1;
		if (!strcasecmp(value, "smart-case")) return 2;
		return -2;
	}
	if (!strcasecmp(name, "refresh-mode")) {
		if (!strcasecmp(value, "manual")) return 0;
		if (!strcasecmp(value, "auto")) return 1;
		if (!strcasecmp(value, "after-command")) return 2;
		if (!strcasecmp(value, "periodic")) return 3;
		return parse_bool(value, &(_tmpint)) ? _tmpint : -2;
	}
	if (!strcasecmp(name, "line-graphics")) {
		if (!strcasecmp(value, "ascii")) return 1;
		if (!strcasecmp(value, "default")) return 0;
		if (!strcasecmp(value, "utf-8") || !strcasecmp(value, "utf8")) return 2;
		if (!strcasecmp(value, "auto")) return -1;
		return parse_bool(value, &(_tmpint)) ? _tmpint : -2;
	}
	if (!strcasecmp(name, "truncation-delimiter")) {
		if (!strcasecmp(value, "utf-8") || !strcasecmp(value, "utf8")) return 1;
		return -2;
	}
	return -2;
}
EOF
echo ok"}

