		if (!strcasecmp(value, "yes") || !strcasecmp(value, "true")) return 1;
		if (!strcasecmp(value, "smart-case")) return 2;
		return -2;
	}
	if (!strcasecmp(name, "refresh-mode")) {
		if (!strcasecmp(value, "manual")) return 0;
		if (!strcasecmp(value, "auto")) return 1;
		if (!strcasecmp(value, "after-command")) return 2;
		if (!strcasecmp(value, "periodic")) return 3;
		if (!strcasecmp(value, "no") || !strcasecmp(value, "false")) return 0;
		if (!strcasecmp(value, "yes") || !strcasecmp(value, "true")) return 1;
		return -2;
	}
	if (!strcasecmp(name, "line-graphics")) {
		if (!strcasecmp(value, "ascii")) return 1;
		if (!strcasecmp(value, "default")) return 0;
		if (!strcasecmp(value, "utf-8") || !strcasecmp(value, "utf8")) return 2;
		if (!strcasecmp(value, "auto")) return -1;
		if (!strcasecmp(value, "no") || !strcasecmp(value, "false")) return 1;
		if (!strcasecmp(value, "yes") || !strcasecmp(value, "true")) return 0;
		return -2;
	}
	if (!strcasecmp(name, "truncation-delimiter")) {
		if (!strcasecmp(value, "utf-8") || !strcasecmp(value, "utf8")) return 1;
		if (!strcasecmp(value, "ascii")) return 0;
		return -2;
	}
	if (!strcasecmp(name, "show-notes")) {
		if (!strcasecmp(value, "no") || !strcasecmp(value, "false")) return 0;
		if (!strcasecmp(value, "yes") || !strcasecmp(value, "true")) return 1;
		return 2;	/* reference */
	}
	if (!strcasecmp(name, "vertical-split")) {
		if (!strcasecmp(value, "auto")) return -1;
		if (!strcasecmp(value, "yes") || !strcasecmp(value, "true")) return 1;
		if (!strcasecmp(value, "no") || !strcasecmp(value, "false")) return 0;
		return -2;
	}
	return -2;
}

static struct option *
find_option(const char *name)
{
	unsigned i;

	for (i = 0; i < ARRAY_SIZE(options); i++)
		if (!strcasecmp(options[i].name, name))
			return &options[i];
	return NULL;
}

struct option *
option_get(const char *name)
{
	return find_option(name);
}

int
option_int(const char *name)
{
	struct option *o = find_option(name);
	return o ? o->ival : 0;
}

char *
option_str(const char *name)
{
	struct option *o = find_option(name);
	return o ? o->sval : NULL;
}

static bool
parse_bool(const char *value, int *ival)
{
	if (!strcasecmp(value, "yes") || !strcasecmp(value, "true") ||
	    !strcasecmp(value, "on") || !strcmp(value, "1")) {
		*ival = 1; return true;
	}
	if (!strcasecmp(value, "no") || !strcasecmp(value, "false") ||
	    !strcasecmp(value, "off") || !strcmp(value, "0")) {
		*ival = 0; return true;
	}
	return false;
}

static bool
parse_pct(const char *value, int *ival)
{
	char *end;
	int n = (int) strtol(value, &end, 10);

	while (*end == ' ') end++;
	if (*end == '%') { *ival = n; return true; }
	if (!*end) { *ival = n; return true; }
	return false;
}

/* apply a setting to the module level variables */
void
sync_option(const char *name, int ival)
{
	if (!strcasecmp(name, "show-changes")) opt_show_changes = ival;
	else if (!strcasecmp(name, "status-show-untracked-dirs")) opt_status_untracked_dirs = ival;
	else if (!strcasecmp(name, "status-show-untracked-files")) opt_status_untracked_files = ival;
	else if (!strcasecmp(name, "tab-size")) opt_tab_size = ival;
	else if (!strcasecmp(name, "diff-context")) opt_diff_context = ival;
	else if (!strcasecmp(name, "split-view-height")) opt_split_height = ival;
	else if (!strcasecmp(name, "split-view-width")) opt_split_width = ival;
	else if (!strcasecmp(name, "horizontal-scroll")) opt_horizontal_scroll = ival;
	else if (!strcasecmp(name, "ignore-space")) opt_ignore_space = ival;
	else if (!strcasecmp(name, "commit-order")) opt_commit_order = ival;
	else if (!strcasecmp(name, "ignore-case")) opt_ignore_case = ival;
	else if (!strcasecmp(name, "mailmap")) opt_mailmap = ival;
	else if (!strcasecmp(name, "wrap-lines")) opt_wrap_lines = ival;
	else if (!strcasecmp(name, "vertical-split")) opt_vertical_split = ival;
	else if (!strcasecmp(name, "refresh-mode")) opt_refresh_mode = ival;
	else if (!strcasecmp(name, "refresh-interval")) opt_refresh_interval = ival;
	else if (!strcasecmp(name, "line-graphics")) opt_line_graphics = ival;
	else if (!strcasecmp(name, "truncation-delimiter")) opt_trunc_delim = ival;
	else if (!strcasecmp(name, "show-notes")) opt_show_notes = ival;
	else if (!strcasecmp(name, "word-diff")) opt_word_diff = ival;
	else if (!strcasecmp(name, "editor-line-number")) opt_editor_line_number = ival;
	else if (!strcasecmp(name, "start-on-head")) opt_start_on_head = ival;
}

void
sync_option_str(const char *name, const char *val)
{
	if (!strcasecmp(name, "diff-options")) { free(opt_diff_options); opt_diff_options = val ? strdup(val) : NULL; }
	else if (!strcasecmp(name, "blame-options")) { free(opt_blame_options); opt_blame_options = val ? strdup(val) : NULL; }
	else if (!strcasecmp(name, "log-options")) { free(opt_log_options); opt_log_options = val ? strdup(val) : NULL; }
	else if (!strcasecmp(name, "main-options")) { free(opt_main_options); opt_main_options = val ? strdup(val) : NULL; }
	else if (!strcasecmp(name, "reference-format")) { free(opt_reference_format); opt_reference_format = val ? strdup(val) : NULL; }
	else if (!strcasecmp(name, "editor")) { free(opt_editor); opt_editor = val ? strdup(val) : NULL; }
	else if (!strcasecmp(name, "git-colors")) { free(opt_git_colors); opt_git_colors = val ? strdup(val) : NULL; }
	else if (!strcasecmp(name, "diff-highlight")) { }
}

bool
option_set(const char *name, const char *value, bool quiet)
{
	struct option *o = find_option(name);
	int ival;

	if (!o) {
		if (!quiet)
			warn("Unknown option name: %s", name);
		return false;
	}
	switch (o->type) {
	case OPT_BOOL:
		if (!parse_bool(value, &ival)) {
			if (!quiet) warn("Invalid boolean value for %s: %s", name, value);
			return false;
		}
		o->ival = ival; sync_option(name, ival);
		break;
	case OPT_INT:
		if (!strncasecmp(value, "0x", 2))
			ival = (int) strtol(value + 2, NULL, 16);
		else
			ival = atoi(value);
		o->ival = ival; sync_option(name, ival);
		break;
	case OPT_PCT:
		if (!parse_pct(value, &ival)) {
			if (!quiet) warn("Invalid percentage value for %s: %s", name, value);
			return false;
		}
		o->ival = ival; sync_option(name, ival);
		break;
	case OPT_ENUM:
		ival = enum_value(o->name, value);
		if (ival == -2) {
			if (!quiet) warn("Invalid value for %s: %s", name, value);
			return false;
		}
		o->ival = ival; sync_option(name, ival);
		break;
	case OPT_STRING:
		free(o->sval);
		o->sval = strdup(value);
		sync_option_str(name, o->sval);
		break;
	}
	return true;
}
