	else if (!strcasecmp(name, "start-on-head")) opt_start_on_head = ival;
}

void
sync_option_str(const char *name, const char *val)
{
	if (!strcasecmp(name, "diff-options")) { free(opt_diff_options); opt_diff_options = val ? strdup(val) : NULL; }
	else if (!strcasecmp(name, "blame-options")) { free(opt_blame_options); opt_blame_options = val ? strdup(val) : NULL; }
	else if (!strcasecmp(name, "log-options")) { free(opt_log_options); opt_log_options = val ? strdup(val) : NULL; }
	else if (!strcasecmp(name, "main-options")) { free(opt_main_options); opt_main_options = val ? strdup(val) : NULL; }
	else if (!strcasecmp(name, "reference-format")) { free(opt_reference_format); opt_reference_format = val ? strdup(val) : NULL; }
	else if (!strcasecmp(name, "editor")) { free(opt_editor); opt_editor = val ? strdup(val) : NULL; }
	else if (!strcasecmp(name, "git-colors")) { free(opt_git_colors); opt_git_colors = val ? strdup(val) : NULL; }
	else if (!strcasecmp(name, "diff-highlight")) { }
}

bool
option_set(const char *name, const char *value, bool quiet)
{
	struct option *o = find_option(name);
	int ival;

	if (!o) {
		if (!quiet)
			warn("Unknown option name: %s", name);
		return false;
	}
	switch (o->type) {
	case OPT_BOOL:
		if (!parse_bool(value, &ival)) {
			if (!quiet) warn("Invalid boolean value for %s: %s", name, value);
			return false;
		}
		o->ival = ival; sync_option(name, ival);
		break;
	case OPT_INT:
		if (!strncasecmp(value, "0x", 2))
			ival = (int) strtol(value + 2, NULL, 16);
		else
			ival = atoi(value);
		o->ival = ival; sync_option(name, ival);
		break;
	case OPT_PCT:
		if (!parse_pct(value, &ival)) {
			if (!quiet) warn("Invalid percentage value for %s: %s", name, value);
			return false;
		}
		o->ival = ival; sync_option(name, ival);
		break;
	case OPT_ENUM:
		ival = enum_value(o->name, value);
		if (ival == -2) {
			if (!quiet) warn("Invalid value for %s: %s", name, value);
			return false;
		}
		o->ival = ival; sync_option(name, ival);
		break;
	case OPT_STRING:
		free(o->sval);
		o->sval = strdup(value);
		sync_option_str(name, o->sval);
		break;
	}
	return true;
}
