static bool
parse_bool(const char *value, int *ival)
{
	if (!strcasecmp(value, "yes") || !strcasecmp(value, "true") ||
	    !strcasecmp(value, "on") || !strcmp(value, "1")) {
		*ival = 1; return true;
	}
	if (!strcasecmp(value, "no") || !strcasecmp(value, "false") ||
	    !strcasecmp(value, "off") || !strcmp(value, "0")) {
		*ival = 0; return true;
	}
	return false;
}

static bool
parse_pct(const char *value, int *ival)
{
	char *end;
	int n = (int) strtol(value, &end, 10);

	while (*end == ' ') end++;
	if (*end == '%') { *ival = n; return true; }
	if (!*end) { *ival = n; return true; }
	return false;
}

