	else if (!strcasecmp(name, "blame-options")) { free(opt_blame_options); opt_blame_options = val ? strdup(val) : NULL; }
	else if (!strcasecmp(name, "log-options")) { free(opt_log_options); opt_log_options = val ? strdup(val) : NULL; }
	else if (!strcasecmp(name, "main-options")) { free(opt_main_options); opt_main_options = val ? strdup(val) : NULL; }
	else if (!strcasecmp(name, "reference-format")) { free(opt_reference_format); opt_reference_format = val ? strdup(val) : NULL; }
