/* ------------------------------------------------------------------ */
/* keys                                                                */
/* ------------------------------------------------------------------ */
/* ncurses key codes (kept in sync with curses.h) */
#define K_DOWN		0402
#define K_UP		0403
#define K_LEFT		0404
#define K_RIGHT		0405
#define K_HOME		0406
#define K_BACKSPACE	0407
#define K_F0		0410
#define K_DC		0512
#define K_IC		0513
#define K_SF		0520
#define K_SR		0521
#define K_NPAGE		0522
#define K_PPAGE		0523
#define K_ENTER		0527
#define K_BTAB		0541
#define K_END		0550

const char *keymap_names[] = {
	"generic", "search", "main", "diff", "reflog", "refs", "status",
	"stage", "stash", "pager", "toggle", "help", "blob", "tree", "grep",
	"view",
};

struct keybinding *bindings[16];
static int nbindings;

int
keyname_to_key(const char *name, int *key)
{
	static const struct { const char *name; int key; const char *alt; } tab[] = {
		{ "Enter",	'\n',	"enter" },
		{ "Tab",	'\t',	"tab" },
		{ "Esc",	27,	"escape" },
		{ "Space",	' ',	"space" },
		{ "Backspace",	K_BACKSPACE, "backspace" },
		{ "Delete",	K_DC,	"delete" },
		{ "Insert",	K_IC,	"insert" },
		{ "Down",	K_DOWN,	"down" },
		{ "Up",		K_UP,	"up" },
		{ "Left",	K_LEFT,	"left" },
		{ "Right",	K_RIGHT, "right" },
		{ "Home",	K_HOME,	"home" },
		{ "End",	K_END,	"end" },
		{ "PageUp",	K_PPAGE, "pageup" },
		{ "PageDown",	K_NPAGE, "pagedown" },
		{ "ScrollFwd",	K_SF,	"scrollfwd" },
		{ "ScrollBack",	K_SR,	"scrollback" },
	};
	unsigned i;
	int len;

	if (name[0] == '<' && (len = strlen(name)) > 2 && name[len-1] == '>') {
		char buf[32];
		if (len-2 >= (int) sizeof(buf)) return false;
		memcpy(buf, name+1, len-2); buf[len-2] = 0;
		for (i = 0; i < ARRAY_SIZE(tab); i++) {
			if (!strcasecmp(buf, tab[i].name) || !strcasecmp(buf, tab[i].alt)) {
				*key = tab[i].key; return true;
			}
		}
		if (!strncasecmp(buf, "Ctrl-", 5) && buf[6] == 0) {
			int c = buf[5];
			*key = toupper(c) - 'A' + 1;
			return true;
		}
		if (buf[0] == 'F' && isdigit((unsigned char) buf[1])) {
			int n = atoi(buf + 1);
			if (n >= 1 && n <= 63) { *key = K_F0 + n; return true; }
		}
		return false;
	}
	if (name[0] == 0 || name[1] != 0)
		return false;
	*key = (unsigned char) name[0];
	return true;
}

static int
key_to_name(int key, char *buf, size_t size)
{
	static const struct { int key; const char *name; } tab[] = {
		{ K_DOWN, "Down" }, { K_UP, "Up" }, { K_LEFT, "Left" },
		{ K_RIGHT, "Right" }, { K_HOME, "Home" }, { K_END, "End" },
		{ K_IC, "Insert" }, { K_DC, "Delete" }, { K_PPAGE, "PageUp" },
		{ K_NPAGE, "PageDown" }, { K_SF, "ScrollFwd" },
		{ K_SR, "ScrollBack" }, { K_BACKSPACE, "Backspace" },
		{ K_ENTER, "Enter" }, { K_BTAB, "BTab" }, { 27, "Esc" },
		{ '\n', "Enter" }, { '\t', "Tab" }, { ' ', "Space" },
	};
	unsigned i;

	if (key >= K_F0 && key < K_F0 + 64) {
		snprintf(buf, size, "F%d", key - K_F0);
		return 1;
	}
	for (i = 0; i < ARRAY_SIZE(tab); i++)
		if (tab[i].key == key) {
			snprintf(buf, size, "%s", tab[i].name);
			return 1;
		}
	if (key >= 1 && key <= 26) {
		snprintf(buf, size, "Ctrl-%c", 'A' + key - 1);
		return 1;
	}
	if (key > 0 && key < 256 && isprint(key)) {
		buf[0] = key; buf[1] = 0;
		return 1;
	}
	return 0;
}

void
binding_add(int keymap, int key, const char *request)
{
	struct keybinding *b = calloc(1, sizeof(*b));
	struct keybinding **p;

	b->keymap = keymap;
	b->key = key;
	b->request = strdup(request);
	nbindings++;
	for (p = &bindings[keymap]; *p; p = &(*p)->next)
		;
	*p = b;
}

const char *
binding_get(int keymap, int key)
{
	struct keybinding *b;

	for (b = bindings[keymap]; b; b = b->next)
		if (b->key == key)
			return b->request;
	return NULL;
}

