void
load_default_bindings(void)
{
	unsigned i;
	int key;

	for (i = 0; i < ARRAY_SIZE(default_bindings); i++) {
		char buf[64];
		const char *keys = default_bindings[i].keys;
		while (*keys) {
			const char *end;
			if (*keys == '<') {
				end = strchr(keys, '>');
				if (!end) break;
				snprintf(buf, sizeof(buf), "%.*s", (int)(end - keys + 1), keys);
				keys = end + 1;
			} else if (keys[0] == '\\' && keys[1] == '\\') {
				buf[0] = '\\'; buf[1] = 0; keys += 2;
			} else {
				buf[0] = *keys; buf[1] = 0; keys++;
			}
			if (!keyname_to_key(buf, &key)) {
				warn("Unknown key name: %s", buf);
				continue;
			}
			binding_add(default_bindings[i].map, key, default_bindings[i].request);
		}
	}
}
