int config_errors;

static void
strip_comment(char *line)
{
	char *p = line;
	bool in_quote = false;

	while (*p) {
		if (*p == '"') in_quote = !in_quote;
		if (*p == '#' && !in_quote) { *p = 0; break; }
		p++;
	}
}

static char *
skip_ws(char *s)
{
	while (*s == ' ' || *s == '\t') s++;
	return s;
}

static void
trim_end(char *s)
{
	size_t n = strlen(s);
	while (n && (s[n-1] == ' ' || s[n-1] == '\t')) s[--n] = 0;
}

static const char *view_names[] = {
