}

static void
handle_set(char *args)
{
	char *eq = strchr(args, '=');
	char name[256], value[1024];

	if (!eq) {
		config_warn("Missing '=' after set");
		return;
	}
	snprintf(name, sizeof(name), "%.*s", (int)(eq - args), args);
	trim_end(name);
	snprintf(value, sizeof(value), "%s", eq + 1);
	trim_end(value);
	if (!option_set(name, value, false))
		config_warn("Unknown option name: %s", name);
}

static void
handle_bind(char *args)
{
	char *sp = strchr(args, ' ');
	char keymap[64], rest[512];
	int km, key;
	char *key, *action;

	if (!sp) { config_warn("Missing arguments to bind"); return; }
	snprintf(keymap, sizeof(keymap), "%.*s", (int)(sp - args), args);
	trim_end(keymap);
	snprintf(rest, sizeof(rest), "%s", sp + 1);
	trim_end(rest);
	km = -1;
	for (km = 0; km < KM_LAST; km++)
		if (!strcasecmp(keymap, keymap_names[km]))
			break;
	if (km >= KM_LAST) { config_warn("Unknown keymap: %s", keymap); return; }
	key = rest;
	action = strchr(rest, ' ');
	if (!action) { config_warn("Missing action for bind"); return; }
	*action = 0;
	trim_end(key);
	action++;
	trim_end(action);
	if (!keyname_to_key(key, &key_idx))
		{ config_warn("Unknown key name: %s", key); return; }
