	binding_add(km, key_idx, action);
}

static void
handle_color(char *args)
{
	char *sp = args;
	char area[128], fgname[64], bgname[64], attr[64];
	int fg, bg, attrval;
	char *p;

	if (*sp == '"') {
		/* quoted custom area */
		p = strchr(sp + 1, '"');
		if (!p) { config_warn("Unterminated string in color"); return; }
		snprintf(area, sizeof(area), "%.*s", (int)(p - sp - 1), sp + 1);
		sp = p + 1;
	} else if (*sp == '/') {
		p = strchr(sp + 1, '/');
		if (!p) { config_warn("Unterminated regexp in color"); return; }
		snprintf(area, sizeof(area), "%s", sp);
		sp = p + 1;
	} else {
		p = sp;
		while (*p && !isspace((unsigned char) *p)) p++;
		snprintf(area, sizeof(area), "%.*s", (int)(p - sp), sp);
		sp = p;
	}
	sp = skip_ws(sp);
	if (!*sp) { config_warn("Missing colors for color command"); return; }
	p = sp;
	while (*p && !isspace((unsigned char) *p)) p++;
	snprintf(fgname, sizeof(fgname), "%.*s", (int)(p - sp), sp);
	sp = skip_ws(p);
	p = sp;
	while (*p && !isspace((unsigned char) *p)) p++;
	snprintf(bgname, sizeof(bgname), "%.*s", (int)(p - sp), sp);
	sp = skip_ws(p);
	attrval = 0;
	while (*sp) {
		p = sp;
		while (*p && !isspace((unsigned char) *p)) p++;
		snprintf(attr, sizeof(attr), "%.*s", (int)(p - sp), sp);
		{
			int a = attr_from_name(attr);
			if (a >= 0) attrval |= a;
		}
		sp = skip_ws(p);
	}
	if (!color_from_name(fgname, &fg, &bg, &attrval)) {
		config_warn("Unknown color: %s", fgname);
		return;
	}
	{
		int bg2;
		if (!color_from_name(bgname, &bg2, &bg, &attrval)) {
			config_warn("Unknown color: %s", bgname);
			return;
		}
	}
	color_set(area, fg, bg, attrval);
}

static void
handle_source(char *args, bool quiet)
{
	bool q = false;
	char path[1024];

	if (!strncasecmp(args, "-q ", 3)) {
		q = true;
		args += 3;
	}
	args = skip_ws(args);
	snprintf(path, sizeof(path), "%s", args);
	trim_end(path);
	read_config(path, q, false);
}

int
read_config(const char *path, bool quiet, bool default_file)
{
	FILE *f = fopen(path, "r");
	char line[2048];
	char pending[4096];
	int plen = 0;
	const char *saved_file = config_file_name;
	int saved_lineno = config_lineno;

	if (!f) {
		if (!quiet)
			warn("Failed to open configuration file %s", path);
		return -1;
	}
	config_file_name = path;
	config_lineno = 0;
	while (fgets(line, sizeof(line), f)) {
		char *cmd;
		config_lineno++;
		chomp(line);
		if (plen) {
			if (plen + strlen(line) >= (int) sizeof(pending)) continue;
			strcpy(pending + plen, line);
			plen += strlen(line);
			if (line[strlen(line)-1] == '\\') { pending[plen-1] = 0; plen--; continue; }
			cmd = pending;
			pending[0] = 0; plen = 0;
		} else {
			size_t n = strlen(line);
			if (n && line[n-1] == '\\') { line[n-1] = 0; strcpy(pending, line); plen = n - 1; continue; }
			cmd = line;
		}
		strip_comment(cmd);
		cmd = skip_ws(cmd);
		if (!*cmd) continue;
		trim_end(cmd);
		if (!strncasecmp(cmd, "set ", 4)) handle_set(skip_ws(cmd + 4));
		else if (!strcasecmp(cmd, "set")) config_warn("Missing arguments to set");
		else if (!strncasecmp(cmd, "bind ", 5)) handle_bind(skip_ws(cmd + 5));
		else if (!strncasecmp(cmd, "color ", 6)) handle_color(skip_ws(cmd + 6));
		else if (!strncasecmp(cmd, "source ", 7)) handle_source(skip_ws(cmd + 7), quiet);
		else if (!strcasecmp(cmd, "bind") || !strcasecmp(cmd, "color") || !strcasecmp(cmd, "source"))
			config_warn("Missing arguments to %s", cmd);
		else config_warn("Unknown command: %s", cmd);
	}
	fclose(f);
	config_file_name = saved_file;
	config_lineno = saved_lineno;
	if (config_errors && !quiet) {
		warn("Errors while loading %s.", path);
		config_errors = 0;
	}
	return 0;
}
