/* ------------------------------------------------------------------ */
/* git config                                                          */
/* ------------------------------------------------------------------ */
static char *git_colors_map = NULL;

static void
handle_git_set(char *name, char *value)
{
	if (!strncasecmp(name, "color.", 6)) {
		char area[128];
		int fg, bg, attr;
		char buf[256];
		char *tok, *save = NULL;

		snprintf(area, sizeof(area), "%s", name + 6);
		snprintf(buf, sizeof(buf), "%s", value);
		{
			char *fgn = strtok_r(buf, " ", &save);
			char *bgn = strtok_r(NULL, " ", &save);
			char *atn;
			if (!fgn) return;
			if (!color_from_name(fgn, &fg, &bg, &attr)) return;
			if (!bgn || !color_from_name(bgn, &bg, &bg, &attr)) { bg = -1; }
			while ((atn = strtok_r(NULL, " ", &save))) {
				int a = attr_from_name(atn);
				if (a >= 0) attr |= a;
			}
		}
		color_set(area, fg, bg, attr);
		return;
	}
	if (!strncasecmp(name, "bind.", 5)) {
		char buf[256];
		char *save = NULL;
		char *key, *act;
		int km = KM_GENERIC, k;
		snprintf(buf, sizeof(buf), "%s", name + 5);
		key = strtok_r(buf, ".", &save);
		if (key) km = -1;
		if (key) { int i; for (i = 0; i < KM_LAST; i++) if (!strcasecmp(key, keymap_names[i])) km = i; }
		if (km < 0) km = KM_GENERIC;
		act = strtok_r(NULL, "", &save);
		(void) act;
		/* value holds the request */
		{
			char vbuf[512];
			char *vsave = NULL, *v;
			snprintf(vbuf, sizeof(vbuf), "%s", value);
			/* git config splits multi-word values; join them */
			(void) vsave;
			key = strtok_r(vbuf, " ", &vsave);
			v = strtok_r(NULL, "", &vsave);
			if (!key || !v) return;
			if (keyname_to_key(key, &k))
				binding_add(km, k, v);
		}
		return;
	}
	/* plain setting inside [tig] */
	{
		char vbuf[512];
		snprintf(vbuf, sizeof(vbuf), "%s", value);
		option_set(name, vbuf, true);
	}
}

void
read_git_config(void)
{
	struct io io;
	char line[SIZEOF_STR];
	char section[256] = "";

	if (!io_open(&io, "git --no-pager config --list"))
		return;
	while (io_get(&io, line, sizeof(line))) {
		char *p = line;
		char name[256], value[1024];
		char *eq;

		if (*p == '[') {
			char *end = strchr(p, ']');
			if (!end) continue;
			snprintf(section, sizeof(section), "%.*s", (int)(end - p - 1), p + 1);
			continue;
		}
		eq = strchr(p, '=');
		if (!eq) continue;
		snprintf(name, sizeof(name), "%.*s", (int)(eq - p), p);
		snprintf(value, sizeof(value), "%s", eq + 1);
		if (!strncasecmp(section, "tig", 3)) {
			char full[512];
			const char *sub = section + 3;
			while (*sub == ' ') sub++;
			if (!*sub)
				snprintf(full, sizeof(full), "%s", name);
			else if (!strcasecmp(sub, "color") && !strstr(name, "."))
				snprintf(full, sizeof(full), "color.%s", name);
			else if (!strcasecmp(sub, "bind"))
				snprintf(full, sizeof(full), "bind.%s", name);
			else if (!strncasecmp(sub, "color.", 6))
				snprintf(full, sizeof(full), "color.%s%s", sub + 6, name);
			else if (!strncasecmp(sub, "bind.", 5))
				snprintf(full, sizeof(full), "bind.%s%s", sub + 5, name);
			else
				snprintf(full, sizeof(full), "%s.%s", sub, name);
			handle_git_set(full, value);
		} else if (!strcasecmp(name, "core.editor")) {
			option_set("editor", value, true);
		} else if (!strcasecmp(name, "core.abbrev")) {
			option_set("id-width", value, true);
		} else if (!strcasecmp(name, "color.ui") || !strcasecmp(name, "color.status")) {
			/* ignored */
		}
	}
	io_status(&io);
	io_free(&io);
}

/* ------------------------------------------------------------------ */
/* reference format                                                    */
/* ------------------------------------------------------------------ */
static char *ref_prefixes[10];

const char *
ref_format_get(int type)
{
	if (!ref_prefixes[type]) {
		switch (type) {
		case REF_BRANCH: return "[%s]";
		case REF_REMOTE: return "<%s>";
		case REF_TRACKED_REMOTE: return "<%s>";
		case REF_TAG: return "<%s>";
		case REF_LOCAL_TAG: return "<%s>";
		case REF_REPLACE: return "<%s>";
		case REF_STASH: return "<%s>";
		case REF_NOTE: return "<%s>";
		case REF_PREFETCH: return "<%s>";
		default: return "[%s]";
		}
	}
	return ref_prefixes[type];
}

static void
parse_reference_format(const char *fmt)
{
	char buf[1024];
	char *tok, *save = NULL;
	int i = 0;

	snprintf(buf, sizeof(buf), "%s", fmt);
	for (tok = strtok_r(buf, " \t", &save); tok && i < 10; tok = strtok_r(NULL, " \t", &save), i++) {
		char *star = strchr(tok, '*');
		char pre[64], post[64];
		if (star) {
			snprintf(pre, sizeof(pre), "%.*s", (int)(star - tok), tok);
			snprintf(post, sizeof(post), "%s", star + 1);
		} else {
			/* e.g. "(branch)" -> prefix "(" suffix ")"? tig uses the
			   whole token as a wrapper around the name */
			size_t n = strlen(tok);
			if (n > 1) {
				snprintf(pre, sizeof(pre), "%.*s", 1, tok);
				snprintf(post, sizeof(post), "%s", tok + n - 1);
			} else { pre[0] = 0; post[0] = 0; }
		}
		free(ref_prefixes[i]);
