#include "draw.h"
#include "config.h"
#include "view.h"

int pair_count = 0;
int utf8_locale = 0;

struct pair { int fg, bg; };
static struct pair pairs[256];

attr_t
color_attr_pair(const char *name, int *fgp, int *bgp)
{
	int fg, bg, attr;
	attr_t a = A_NORMAL;

	if (!color_get(name, &fg, &bg, &attr))
		return A_NORMAL;
	if (fgp) *fgp = fg;
	if (bgp) *bg = bg;
	/* find or create pair */
	{
		int i;
		for (i = 0; i < pair_count; i++)
			if (pairs[i].fg == fg && pairs[i].bg == bg)
				break;
		if (i == pair_count && pair_count < 250) {
			pairs[pair_count].fg = fg;
			pairs[pair_count].bg = bg;
			init_pair(pair_count + 1, fg, bg);
			pair_count++;
		}
		a = COLOR_PAIR(i + 1);
	}
	if (attr & A_BOLD) a |= A_BOLD;
	if (attr & A_UNDERLINE) a |= A_UNDERLINE;
	if (attr & A_REVERSE) a |= A_REVERSE;
	if (attr & A_STANDOUT) a |= A_STANDOUT;
	if (attr & A_DIM) a |= A_DIM;
	if (attr & A_BLINK) a |= A_BLINK;
	return a;
}

attr_t
color_attr(const char *name)
{
	return color_attr_pair(name, NULL, NULL);
}

void
draw_init(void)
{
	const char *loc = setlocale(LC_ALL, "");
	if (loc && (strstr(loc, "UTF-8") || strstr(loc, "utf8")))
		utf8_locale = 1;
	{
		int fg, bg, attr;
		color_get("default", &fg, &bg, &attr);
		start_color();
		use_default_colors();
	}
	/* pre-create the pairs used most */
	{
		unsigned i;
		for (i = 0; i < ARRAY_SIZE(color_table); i++)
			color_attr(color_table[i].name);
	}
}
EOF
echo ok"}

