#include "view.h"
#include "draw.h"
#include "io.h"
#include "config.h"
#include <wchar.h>
#include <wctype.h>

struct view *display[2];
int display_size = 1;
int current_view = 0;
struct view *views[VIEW_COUNT];
bool pager_mode = false;
const char *search_pattern = NULL;
bool option_menu_active = false;
int option_menu_index = 0;
char *file_args = NULL, *rev_args = NULL, *cmdline_args = NULL;
char *open_file = NULL, *goto_commit_id = NULL;
struct commit *commit_list = NULL;
struct ref *ref_list = NULL;
char head_id[41] = "";
char *branch_name = NULL;
int graph_enabled = 1;
regex_t search_re;
bool search_back = false;

/* ------------------------------------------------------------------ */
struct view *
get_view(int id)
{
	if (id < 0 || id >= VIEW_COUNT) return NULL;
	return views[id];
}

struct view *
view_create(int id)
{
	struct view *v = calloc(1, sizeof(struct view));

	views[id] = v;
	v->name = view_names[id];
	return v;
}

void
view_grow(struct view *view, int nlines)
{
	if (view->lines + nlines > view->lines_alloc) {
		int na = view->lines_alloc ? view->lines_alloc * 2 : 64;
		while (na < view->lines + nlines) na *= 2;
		view->line = realloc(view->line, na * sizeof(struct line));
		view->lines_alloc = na;
	}
	memset(view->line + view->lines, 0, nlines * sizeof(struct line));
	view->lines += nlines;
}

void
free_lines(struct view *view)
{
	int i;
	for (i = 0; i < view->lines; i++) {
		free(view->line[i].data);
	}
	view->lines = 0;
	if (view->line) { free(view->line); view->line = NULL; }
	view->lines_alloc = 0;
}

/* ------------------------------------------------------------------ */
/* drawing                                                             */
/* ------------------------------------------------------------------ */
void
draw_view_buf(WINDOW *win, struct drawbuf *buf, int row, int col_offset, int width)
{
	int i, x = 0;
	attr_t cur = 0;
	bool started = false;

	wmove(win, row, 0);
	for (i = 0; i < buf->len; i++) {
		int col = i - col_offset;
		if (col < 0) continue;
		if (col >= width) break;
		if (!started || buf->attrs[i] != cur) {
			if (started) wattroff(win, cur);
			wattron(win, buf->attrs[i]);
			cur = buf->attrs[i];
			started = true;
		}
		mvwaddch(win, row, col, buf->cells[i]);
	}
	/* fill the rest with the default colour */
	if (started) wattroff(win, cur);
	if (x < width) {
		wattron(win, color_attr("default"));
		for (; x < width; x++) {
			int col = x;
			if (col < 0) continue;
			if (col >= width) break;
			mvwaddch(win, row, col, ' ');
		}
		wattroff(win, color_attr("default"));
	}
}
EOF
echo ok"}

