#include "draw.h"
#include "config.h"
#include "view.h"
#include <locale.h>
#include <string.h>
#include <stdio.h>

int utf8_locale = 0;

static int pair_used = 0;
static int pair_fg[256], pair_bg[256];

int
find_or_create_pair(int fg, int bg)
{
	int i;
	for (i = 0; i < pair_used; i++)
		if (pair_fg[i] == fg && pair_bg[i] == bg)
			return COLOR_PAIR(i + 1);
	if (pair_used >= 250)
		return 0;
	pair_fg[pair_used] = fg;
	pair_bg[pair_used] = bg;
	init_pair(pair_used + 1, fg, bg);
	pair_used++;
	return COLOR_PAIR(pair_used);
}

attr_t
color_attr(const char *name)
{
	int fg, bg, attr;

	if (!color_get(name, &fg, &bg, &attr))
		return A_NORMAL;
	return (attr_t) (find_or_create_pair(fg, bg) | attr);
}

/* view specific colours fall back to the global area name */
attr_t
color_attr_named(const char *view, const char *name)
{
	char buf[128];

	snprintf(buf, sizeof(buf), "%s.%s", view, name);
	if (color_get(buf, NULL, NULL, NULL))
		return color_attr(buf);
	return color_attr(name);
}

void
draw_init(void)
{
	const char *loc;

	setlocale(LC_ALL, "");
	loc = setlocale(LC_CTYPE, NULL);
	if (loc && (strcasestr_((char *) loc, "utf") ))
		utf8_locale = 1;
	if (!utf8_locale && getenv("LC_ALL") && strcasestr_(getenv("LC_ALL"), "utf"))
		utf8_locale = 1;
	start_color();
	use_default_colors();
	{
		unsigned i;
		for (i = 0; i < ARRAY_SIZE(color_table); i++)
			color_attr(color_table[i].name);
	}
}
EOF
