 * lines 1..n are the branches spawned by merge commits.  Each line has a
 * column (0 for main, 2, 4, ... for branches), a vertical span of rows and
 * a set of node rows.  Merge commits draw a connector from their node to
 * the branch column; when the branch line already occupies the merge row
 * the connector is routed around it. */

struct gline {
	int col;		/* column of the line */
	int idx;		/* line index (0 = main) */
	int top, bottom;	/* row span (inclusive) of the vertical */
	int color;		/* palette index */
