					if (glines[m].col <= col) continue;
					if (row >= glines[m].top && row <= glines[m].bottom) {
						cornerkind = 9;
						break;
					}
				}
				if (m >= nglines) cornerkind = 5;
			}
			if (col - 1 >= 0) {
				grid[col-1].c = graph_char(1);
				grid[col-1].color = L->color;
				grid[col-1].drawn = true;
			}
			grid[col].c = graph_char(cornerkind);
			grid[col].color = L->color;
			grid[col].drawn = true;
			continue;
		}
