/* ---- rendering ---- */
struct gcell { int ch; wchar_t c; int color; bool drawn; };
static struct gcell grid[MAX_COLS];

static bool
line_occupies(int idx, int row)
{
	struct gline *L = &glines[idx];

	if (row < L->top || row > L->bottom) return false;
	if (L->col == 0) return false;
	if (line_of[row] == idx) return true;		/* node */
	if (row > L->top && row < L->bottom) return true;
	if (row == L->bottom) return true;
	return false;
}

int
graph_render(int row, struct drawbuf *buf, int *maxcol_out)
{
	int i, j, k, n;
	struct commit *c;
	int gcell_color(int idx);

	if (row < 0 || row >= graph_rows) return 0;
	for (i = 0; i < graph_maxcol; i++) {
		grid[i].drawn = false;
		grid[i].c = ' ';
		grid[i].color = 0;
	}
	c = grows[row];

	/* pass 1: merge connectors */
	for (k = 1; k < c->nparents; k++) {
		struct commit *pp = c->parents[k];
		struct gline *L;
		int prow, colL, r;
		int ccolor;

		if (!pp) continue;
		for (prow = 0; prow < graph_rows && grows[prow] != pp; prow++)
			;
		if (prow >= graph_rows) continue;
		for (i = 1; i < nglines; i++)
			if (line_of[prow] == glines[i].idx) break;
		if (i >= nglines) continue;
		L = &glines[i];
		colL = L->col;
		ccolor = colL == 2 ? 1 : 2;

		if (!line_occupies(i, row)) {
			/* straight connector */
			for (j = 1; j < colL; j++) {
				grid[j].c = graph_char(1);
				grid[j].color = ccolor;
				grid[j].drawn = true;
			}
			grid[colL].c = graph_char(3);	/* ur corner */
			grid[colL].color = ccolor;
			grid[colL].drawn = true;
		} else {
			/* detour around the occupied column */
			int cd = -1;
			for (j = 1; ; j++) {
				int col2 = 2 * j, m, free1 = 1;
				if (col2 >= MAX_COLS) break;
				for (m = 1; m < nglines; m++) {
					int rr;
					if (glines[m].col != col2) continue;
					for (rr = row; rr <= prow; rr++)
						if (line_occupies(m, rr)) { free1 = 0; break; }
					if (!free1) break;
				}
				if (free1 && col2 > colL) { cd = col2; break; }
			}
			if (cd < 0) cd = colL;
			for (j = 1; j < cd; j++) {
				grid[j].c = graph_char(1);
				grid[j].color = ccolor;
				grid[j].drawn = true;
			}
			grid[cd].c = graph_char(3);
			grid[cd].color = ccolor;
			grid[cd].drawn = true;
			for (r = row + 1; r < prow; r++) {
				grid[cd].c = graph_char(0);
				grid[cd].color = ccolor;
				grid[cd].drawn = true;
			}
			if (prow != row) {
				grid[cd].c = graph_char(5);	/* lr corner */
				grid[cd].color = ccolor;
				grid[cd].drawn = true;
				for (j = colL + 1; j < cd; j++) {
					grid[j].c = graph_char(1);
					grid[j].color = ccolor;
					grid[j].drawn = true;
				}
			}
		}
	}

	/* pass 2: lines */
	for (i = 0; i < nglines; i++) {
		struct gline *L = &glines[i];
		int col = L->col;
		bool is_node = (line_of[row] == L->idx);
		bool joining = (col > 0 && row == L->bottom && !is_node);
		int cornerkind;

		if (row < L->top || row > L->bottom) continue;
		if (is_node) {
			if (col > 0) {
				grid[col-1].c = ' ';
				grid[col-1].color = -2;	/* graph-commit */
				grid[col-1].drawn = true;
			}
			grid[col].c = graph_node_char(node_type(grows[row]));
			grid[col].color = -2;
			grid[col].drawn = true;
			continue;
		}
		if (col == 0) {
			if (row > L->top) {
				grid[0].c = graph_char(0);
				grid[0].color = L->color;
				grid[0].drawn = true;
			}
			continue;
		}
		if (joining) {
			/* corner char: lr if this is the rightmost joining line
			 * with nothing further right, else btee */
			cornerkind = 9;	/* btee */
			{
				int m;
				for (m = 0; m < nglines; m++) {
					if (m == i) continue;
					if (glines[m].col <= col) continue;
					if (row >= glines[m].top && row <= glines[m].bottom) {
						cornerkind = 9;
						break;
					}
				}
				if (m >= nglines) cornerkind = 5;
			}
			if (col - 1 >= 0) {
				grid[col-1].c = graph_char(1);
				grid[col-1].color = L->color;
				grid[col-1].drawn = true;
			}
			grid[col].c = graph_char(cornerkind);
			grid[col].color = L->color;
			grid[col].drawn = true;
			continue;
		}
		if (row > L->top && row < L->bottom) {
			if (col > 0) {
				grid[col-1].c = ' ';
				grid[col-1].color = L->color;
				grid[col-1].drawn = true;
			}
			grid[col].c = graph_char(0);
			grid[col].color = L->color;
			grid[col].drawn = true;
			continue;
		}
		/* row == L->top (merge row): nothing drawn by the line */
	}

	/* emit */
	n = 0;
	for (i = 0; i < graph_maxcol; i++) {
		if (!grid[i].drawn) continue;
		buf_add(buf, graph_commit_color_attr(), &grid[i].c, 1);
	}
	return n;
}
