buf_reset(struct drawbuf *b) { b->len = 0; }

void
buf_add(struct drawbuf *b, const wchar_t *text, int len, attr_t attr)
{
	int i;
	for (i = 0; i < len; i++) {
		if (b->len >= MAX_COLS) return;
		b->cells[b->len] = text[i];
		b->attrs[b->len] = attr;
		b->len++;
	}
}

void
buf_addw(struct drawbuf *b, const wchar_t *text, attr_t attr)
{
	int n = wcslen(text);
	buf_add(b, text, n, attr);
}

static int
utf8_to_wide(const char *s, wchar_t *out, int max)
{
	int n = mbstowcs(out, s, max);
	return n < 0 ? 0 : n;
}

void
buf_addstr(struct drawbuf *b, const char *text, attr_t attr)
{
	wchar_t w[MAX_COLS];
	int n;

	if (!text) return;
	n = utf8_to_wide(text, w, MAX_COLS);
	buf_add(b, w, n, attr);
}

void
buf_addch(struct drawbuf *b, wchar_t ch, attr_t attr)
{
	if (b->len >= MAX_COLS) return;
	b->cells[b->len] = ch;
	b->attrs[b->len] = attr;
	b->len++;
}

void
buf_pad(struct drawbuf *b, int width, attr_t attr)
{
	while (b->len < width)
		buf_addch(b, ' ', attr);
}

void
buf_printf(struct drawbuf *b, attr_t attr, const char *fmt, ...)
{
	char s[4096];
	va_list args;

	va_start(args, fmt);
	vsnprintf(s, sizeof(s), fmt, args);
	va_end(args);
	buf_addstr(b, s, attr);
}

/* ------------------------------------------------------------------ */
/* view lifecycle                                                      */
/* ------------------------------------------------------------------ */
struct view *
get_view(int id)
{
	if (id < 0 || id >= VIEW_COUNT) return NULL;
	return views[id];
}

static void
add_line(struct view *view, int type, void *data)
{
	if (view->lines >= view->lines_alloc) {
		int na = view->lines_alloc ? view->lines_alloc * 2 : 256;
		view->line = realloc(view->line, na * sizeof(struct line));
		view->lines_alloc = na;
	}
	memset(&view->line[view->lines], 0, sizeof(struct line));
	view->line[view->lines].type = type;
	view->line[view->lines].data_ptr = data;
	view->lines++;
}

void
clear_lines(struct view *view)
{
	int i;
	for (i = 0; i < view->lines; i++)
		if (view->line[i].data_ptr) free(view->line[i].data_ptr);
	view->lines = 0;
}

void
view_grow(struct view *view, int nlines)
{
	add_line(view, LT_DEFAULT, NULL);
	view->lines--;
}

static bool
open_driver(struct view *view)
{
	switch (view->id) {
	case VIEW_MAIN: return open_main_view(view);
	case VIEW_DIFF: return open_diff_view(view, false);
	case VIEW_LOG: return open_log_view(view);
	case VIEW_REFLOG: return open_reflog_view(view);
	case VIEW_PAGER: return open_pager_view(view);
	case VIEW_HELP: return open_help_view_driver(view);
	case VIEW_STATUS: return open_status_view(view);
	case VIEW_STAGE: return open_stage_view(view);
	case VIEW_TREE: return open_tree_view(view);
	case VIEW_BLOB: return open_blob_view(view);
	case VIEW_BLAME: return open_blame_view(view, open_file);
	case VIEW_REFS: return open_refs_view(view);
	case VIEW_STASH: return open_stash_view(view);
	case VIEW_GREP: return open_grep_view(view, NULL);
	}
	return false;
}

bool
view_open_driver(int id, struct view *parent)
{
	struct view *v = views[id];

	if (!v) {
		v = calloc(1, sizeof(struct view));
		views[id] = v;
		v->id = id;
		v->name = view_names[id];
	}
	if (v->parent != parent) {
		clear_lines(v);
		v->parent = parent;
		v->offset = 0;
		v->lineno = 0;
		v->col_offset = 0;
	}
	if (!open_driver(v))
		return false;
	/* push onto the display stack */
	if (display_size < 2) {
		display[display_size++] = v;
		current_view = display_size - 1;
	} else {
		display[current_view] = v;
	}
	return true;
}

void
view_open(int id)
{
	view_open_driver(id, NULL);
}

void
view_close(struct view *view)
{
	int i, j;

	for (i = 0; i < display_size; i++) {
		if (display[i] == view) {
			for (j = i; j < display_size - 1; j++) display[j] = display[j+1];
			display_size--;
			if (current_view >= display_size)
				current_view = display_size - 1;
			if (current_view < 0) current_view = 0;
			break;
		}
	}
	if (view->has_search) { regfree(&view->search_re); view->has_search = false; }
	clear_lines(view);
	if (display_size == 0)
		quit_all();
}

void
view_back(void)
{
	/* tig's < key returns to the previous view state; approximate by
	 * closing the current view */
	if (display_size > 1) {
		view_close(display[current_view]);
	} else
		status_message("No previous view to scroll to");
}
