			if (!strncmp(base, "heads/", 6)) { base += 6; type = 'b'; }
			else if (!strncmp(base, "tags/", 5)) { base += 5; type = 't'; }
			else if (!strncmp(base, "remotes/", 8)) { base += 8; type = 'r'; }
			else if (!strncmp(base, "stash", 5)) { base += 5; type = 's'; }
			else if (!strncmp(base, "notes/", 6)) { base += 6; type = 'n'; }
			else { base = name; type = 'o'; }
		} else {
			base = name;
			type = 'o';
		}
		if (!strcmp(base, "HEAD")) continue;
		ref_new(base, id, type);
	}
	io_status(&io);
	io_free(&io);
}

/* find the refs pointing to a commit */
