commit_refs(struct commit *c, int *count)
{
	struct ref *r, *first = NULL, *last = NULL;
	int n = 0;

	for (r = ref_list; r; r = r->next) {
		if (!strncmp(r->id, c->id, 40)) {
			struct ref *copy = calloc(1, sizeof(*copy));
			copy->name = strdup(r->name);
			copy->type = r->type;
			if (last) last->next = copy; else first = copy;
			last = copy;
			n++;
		}
	}
	if (count) *count = n;
	return first;
}
