/* Read one record terminated by 'term' (e.g. 3 for ETX). */
bool
io_get_record(struct io *io, char *buf, size_t size, int term)
{
	size_t n = 0;
	int c = EOF;

	if (!io->pipe)
		return false;
	for (;;) {
		c = fgetc(io->pipe);
		if (c == EOF)
			break;
		if (c == term)
			break;
		if (n + 1 < size)
			buf[n++] = c;
	}
	buf[n] = 0;
	if (n == 0 && c == EOF)
		return false;
	return true;
}
