/* ------------------------------------------------------------------ */
/* date helpers                                                        */
/* ------------------------------------------------------------------ */
static void
parse_date(const char *s, time_t *t, int *tzmin, char *tz, size_t tzs)
{
	long v = 0;
	char *end;

	*t = 0; *tzmin = 0;
	if (tz) tz[0] = 0;
	if (!s || !*s) return;
	v = strtol(s, &end, 10);
	*t = (time_t) v;
	while (*end == ' ') end++;
	if (*end) {
		char sign = *end;
		int hh = 0, mm = 0;
		if ((sign == '+' || sign == '-') && strlen(end) >= 5) {
			hh = (end[1] - '0') * 10 + (end[2] - '0');
			mm = (end[3] - '0') * 10 + (end[4] - '0');
			*tzmin = hh * 60 + mm;
			if (sign == '-') *tzmin = -*tzmin;
			if (tz) snprintf(tz, tzs, "%s", end);
		} else if (tz) {
			snprintf(tz, tzs, "%s", end);
		}
	}
}

static void
format_date(struct drawbuf *b, time_t t, int tzmin, const char *tz, const char *fmt, attr_t attr)
{
	char buf[256];
	struct tm tm;
	time_t tt = t + (time_t) tzmin * 60;

	gmtime_r(&tt, &tm);
	if (fmt) {
		char tmp[256];
		strftime(tmp, sizeof(tmp), fmt, &tm);
		/* expand %z with the timezone */
		if (tz && strchr(fmt, 'z')) {
			/* strftime %z gives the local zone; replace it */
			char out[256];
			char *p = tmp, *q = out;
			while (*p && q < out + sizeof(out) - 2) {
				if (p[0] == '%' && p[1] == 'z') {
					snprintf(q, out + sizeof(out) - q, "%s", tz ? tz : "+0000");
					q += strlen(q);
					p += 2;
					continue;
				}
				*q++ = *p++;
			}
			*q = 0;
			buf_addstr(b, out, attr);
			return;
		}
		buf_addstr(b, tmp, attr);
		return;
	}
	strftime(buf, sizeof(buf), "%Y-%m-%d %H:%M", &tm);
	if (tz && *tz) {
		size_t l = strlen(buf);
		snprintf(buf + l, sizeof(buf) - l, " %s", tz);
	}
	buf_addstr(b, buf, attr);
}

static void
format_date_noloc(char *out, size_t size, time_t t, int tzmin, const char *tz, const char *fmt)
{
	struct tm tm;
	time_t tt = t + (time_t) tzmin * 60;

	gmtime_r(&tt, &tm);
	if (fmt && *fmt) {
		strftime(out, size, fmt, &tm);
		return;
	}
	if (tz && *tz)
		strftime(out, size, "%Y-%m-%d %H:%M %z", &tm);
	else
		strftime(out, size, "%Y-%m-%d %H:%M", &tm);
}

/* author display: 0 = full, 1 = abbreviated, 2 = email, 3 = email-user */
static void
format_author(struct drawbuf *b, const char *name, const char *email, int display, attr_t attr)
{
	char buf[256];

	if (!name || !*name) return;
	switch (display) {
	case 1: {	/* abbreviated: initials */
		const char *p = name;
		int i = 0;
		bool word = true;
		while (*p && i < (int) sizeof(buf) - 1) {
			if (word && !isspace((unsigned char) *p)) buf[i++] = *p;
			word = isspace((unsigned char) *p);
			p++;
		}
		buf[i] = 0;
		break;
	}
	case 2:
		snprintf(buf, sizeof(buf), "%s", email ? email : "");
		break;
	case 3:
		snprintf(buf, sizeof(buf), "%s", email ? email : "");
		{ char *at = strchr(buf, '@'); if (at) *at = 0; }
		break;
	default:
		snprintf(buf, sizeof(buf), "%s", name);
		break;
	}
	buf_addstr(b, buf, attr);
}
EOF
echo ok"}

