{"command": "cat >> /workspace/src/view.c <<'EOF'

/* pseudo commit state */
bool untracked_changes, unstaged_changes, staged_changes;
time_t pseudo_date;
int pseudo_date_tz = 0;
char pseudo_date_tzs[12] = "+0000";

static void
check_changes(void)
{
	struct io io;
	char line[SIZEOF_STR];

	untracked_changes = unstaged_changes = staged_changes = false;
	if (!opt_show_changes) return;
	if (!io_open(&io, "git status --porcelain -z --untracked-files=normal"))
		return;
	io.nulmode = true;
	while (io_get(&io, line, sizeof(line))) {
		if (line[0] == '?' && line[1] == '?') untracked_changes = true;
		else if (line[0] == ' ' && line[1] != ' ') unstaged_changes = true;
		else if (line[0] != ' ' && line[1] == ' ') staged_changes = true;
		else if (line[0] != ' ' && line[1] != ' ') { staged_changes = true; unstaged_changes = true; }
	}
	io_status(&io);
	io_free(&io);
	time(&pseudo_date);
}

static attr_t
ref_label_attr(struct ref *r)
{
	bool is_head = (r->type == 'b' && branch_name && !strcmp(r->name, branch_name));

	switch (r->type) {
	case 'b': return color_attr(is_head ? "main-head" : "main-ref");
	case 't': return color_attr(r->type == 'b' ? "main-tag" : "main-tag");
	case 'r': return color_attr("main-remote");
	case 's': return color_attr("main-stash");
	case 'n': return color_attr("main-note");
	default: return color_attr("main-other");
	}
}

const char *
ref_format(char type)
{
	switch (type) {
	case 'b': return "[%s]";
	case 't': return "<%s>";
	case 'r': return "<%s>";
	case 's': return "<%s>";
	case 'n': return "<%s>";
	default: return "[%s]";
	}
}

int
node_type(struct commit *c)
{
	if (c->nparents == 0) return 1;		/* root */
	if (c->nparents > 1) return 2;		/* merge */
	return 0;
}

attr_t
graph_commit_color_attr(void)
{
	return color_attr("graph-commit");
}

static void
load_commits(struct view *view)
{
	struct io io;
	char rec[SIZEOF_STR];
	struct view_columns *col = view_columns[VIEW_MAIN];
	char fmt[2048];
	const char *opts = opt_main_options ? opt_main_options : "";
	const char *args = cmdline_args ? cmdline_args : "";
	const char *paths = file_args ? file_args : "";
	bool topo = (opt_commit_order == 0 && graph_enabled);

	/* clear the old commit list */
	{
		struct commit *c = commit_list;
		while (c) { struct commit *n = c->next; free(c); c = n; }
		commit_list = NULL;
	}
	clear_lines(view);
	snprintf(fmt, sizeof(fmt),
		 "git log --encoding=UTF-8 %s%s%%s --date=raw --parents "
		 "--no-color --show-notes --pretty=format:commit "
		 "%%%%m %%%%H %%%%P%%x00%%%%aN <%%%%aE> %%%%ad%%x00%%%%cN "
		 "<%%%%cE> %%%%cd%%x00%%%%s%%x00%%%%N%%x03 -- %s",
		 topo ? "--topo-order " : "", *args ? args : (*args ? "" : ""), paths);
	/* rebuild: we must place the args before --date=raw */
	snprintf(fmt, sizeof(fmt),
		 "git log --encoding=UTF-8 %s%s --date=raw --parents "
		 "--no-color --show-notes --pretty=format:commit "
		 "%%%%m %%%%H %%%%P%%x00%%%%aN <%%%%aE> %%%%ad%%x00%%%%cN "
		 "<%%%%cE> %%%%cd%%x00%%%%s%%x00%%%%N%%x03 -- %s",
		 topo ? "--topo-order " : "", args, paths);
	(void) opts;
	io.nulmode = false;
	if (!io_open(&io, "%s", fmt)) {
		status_error_msg("No revisions match the given arguments.");
		return;
	}
	while (io_get_record(&io, rec, sizeof(rec), 3)) {
		char *fields[8];
		int nf = 0;
		char *p = rec;
		struct commit *c;

		fields[nf++] = p;
		while (*p && nf < 8) {
			if (*p == 0) { *p = 0; fields[nf++] = p + 1; }
			p++;
		}
		if (nf < 5) continue;
		c = commit_new();
		/* field 0: "commit <tag> <id> <parents>" */
		{
			char *q = fields[0];
			if (!strncmp(q, "commit ", 7)) {
				q += 7;
				while (*q && *q != ' ') q++;   /* tag */
				while (*q == ' ') q++;
				strncpy(c->id, q, 40);
				while (*q && *q != ' ') q++;
				while (*q == ' ') q++;
				if (*q) {
					char *tmp = strdup(q);
					char *tok, *save = NULL;
					int n = 0;
					c->parent_ids = calloc(9, sizeof(char *));
					for (tok = strtok_r(tmp, " ", &save); tok && n < 8;
					     tok = strtok_r(NULL, " ", &save))
						c->parent_ids[n++] = strdup(tok);
					free(tmp);
				}
			}
		}
		/* field 1: author "<name> <<email>> <date>" */
		{
			char *q = fields[1];
			char *lt = strrchr(q, '<');
			char *gt = strrchr(q, '>');
			char *end;
			if (lt && gt && gt > lt) {
				char *nameend = lt;
				while (nameend > q && nameend[-1] == ' ') nameend--;
				c->author = strndup(q, nameend - q);
				c->author_email = strndup(lt + 1, gt - lt - 1);
				q = gt + 1;
			}
			while (*q == ' ') q++;
			end = strchr(q, 0);
			parse_date(q, &c->cdate, &c->cdate_tz, c->cdate_tzs, sizeof(c->cdate_tzs));
			c->author_date = c->cdate;
		}
		/* field 2: committer */
		{
			char *q = fields[2];
			char *lt = strrchr(q, '<');
			char *gt = strrchr(q, '>');
			char *d;
			if (lt && gt && gt > lt) {
				char *nameend = lt;
				while (nameend > q && nameend[-1] == ' ') nameend--;
				c->committer = strndup(q, nameend - q);
				c->committer_email = strndup(lt + 1, gt - lt - 1);
				q = gt + 1;
			}
			while (*q == ' ') q++;
			parse_date(q, &c->adate, &c->adate_tz, c->adate_tzs, sizeof(c->adate_tzs));
			(void) d;
		}
		c->title = strdup(fields[3]);
		(void) fields[4];
		add_line(view, LT_COMMIT, NULL);
		view->line[view->lines-1].commit = c;
	}
	io_status(&io);
	io_free(&io);
	if (io.status != 0) {
		status_error_msg("No revisions match the given arguments.");
	}
	check_changes();
