/* ------------------------------------------------------------------ */
/* generic text line classification (log / diff / pager)               */
/* ------------------------------------------------------------------ */
enum text_kind {
	TK_DEFAULT, TK_COMMIT, TK_AUTHOR, TK_COMMITTER, TK_DATE, TK_REFS,
	TK_MERGE, TK_DIFF_HEADER, TK_DIFF_INDEX, TK_DIFF_CHUNK, TK_DIFF_ADD,
	TK_DIFF_DEL, TK_DIFF_ADD2, TK_DIFF_DEL2, TK_DIFF_STAT, TK_PARENT,
	TK_TREE, TK_MESSAGE,
};

static enum text_kind
classify(const char *s)
{
	if (!strncmp(s, "commit ", 7)) return TK_COMMIT;
	if (!strncmp(s, "parent ", 7)) return TK_PARENT;
	if (!strncmp(s, "tree ", 5)) return TK_TREE;
	if (!strncmp(s, "Author:", 7)) return TK_AUTHOR;
	if (!strncmp(s, "AuthorDate:", 11)) return TK_DATE;
	if (!strncmp(s, "Commit:", 7)) return TK_COMMITTER;
	if (!strncmp(s, "Committer:", 10)) return TK_COMMITTER;
	if (!strncmp(s, "CommitDate:", 11)) return TK_DATE;
	if (!strncmp(s, "Date:", 5)) return TK_DATE;
	if (!strncmp(s, "Merge:", 6)) return TK_MERGE;
	if (!strncmp(s, "Refs:", 5)) return TK_REFS;
	if (!strncmp(s, "diff --git ", 11)) return TK_DIFF_HEADER;
	if (!strncmp(s, "diff --cc ", 10)) return TK_DIFF_HEADER;
	if (!strncmp(s, "diff --combined ", 16)) return TK_DIFF_HEADER;
	if (!strncmp(s, "index ", 6)) return TK_DIFF_INDEX;
