static void
render_diffstat_line(struct view *view, struct line *l, struct drawbuf *b, const char *text)
{
	attr_t statattr = color_attr("diff-stat");
	attr_t defattr = color_attr("default");
	attr_t addattr = color_attr("diff-add");
	attr_t delattr = color_attr("diff-del");
	const char *p = strstr(text, " | ");
	int nlen;

	buf_reset(b);
	if (!p) { buf_addstr(b, text, defattr); return; }
	nlen = p - text + 1;	/* include the space before the | */
	buf_addstr(b, strndup_(text, nlen), statattr);
	p += 3;		/* skip " | " */
	/* counts up to the symbol run */
	{
		const char *sym = p;
		while (*sym && (isdigit((unsigned char)*sym) || *sym == ' ' || *sym == '|'))
			sym++;
		buf_addstr(b, strndup_(p, sym - p), defattr);
		/* symbol runs */
		while (*sym) {
			const char *run = sym;
			if (*sym == '+') {
				while (*sym == '+') sym++;
				buf_addstr(b, strndup_(run, sym - run), addattr);
			} else if (*sym == '-') {
				while (*sym == '-') sym++;
				buf_addstr(b, strndup_(run, sym - run), delattr);
			} else {
				while (*sym && *sym != '+' && *sym != '-') sym++;
				buf_addstr(b, strndup_(run, sym - run), defattr);
			}
		}
	}
}

/* highlight the title overflow */
static void
add_overflow(struct drawbuf *b, const char *text, attr_t attr, attr_t oattr, int maxw)
{
	int len = strlen(text);

	if (maxw > 0 && len > maxw) {
		buf_addstr(b, strndup_(text, maxw), attr);
		buf_addstr(b, text + maxw, oattr);
	} else
		buf_addstr(b, text, attr);
}

/* ------------------------------------------------------------------ */
/* log / diff / stage / pager                                          */
/* ------------------------------------------------------------------ */
static void
read_pipe_lines(struct view *view, struct io *io, int basetype)
{
	char line[8192];

	while (io_get(io, line, sizeof(line))) {
		struct line *l;
		view_grow(view, 1);
		l = &view->line[view->lines - 1];
		l->type = basetype;
		l->text = strdup(line);
		l->lineno = view->lines;
	}
}

static bool
run_log(struct view *view, const char *cmdfmt)
{
	struct io io;

	io.nulmode = false;
	if (!io_open(&io, "%s", cmdfmt)) {
		status_error_msg("No revisions match the given arguments.");
		return false;
	}
	read_pipe_lines(view, &io, LT_DEFAULT);
	io_status(&io);
	io_free(&io);
	if (io.status != 0) {
		status_error_msg("No revisions match the given arguments.");
		return false;
	}
	return true;
}

static void
insert_refs_lines(struct view *view)
{
	int i;

	for (i = 0; i < view->lines; i++) {
		struct line *l = &view->line[i];
		struct ref *r;
		char buf[1024] = "";
		bool first = true;

		if (!l->text || strncmp(l->text, "commit ", 7)) continue;
		{
			const char *id = l->text + 7;
			for (r = ref_list; r; r = r->next) {
				char rb[512];
				if (strncmp(r->id, id, 40)) continue;
				snprintf(rb, sizeof(rb), "%s%s%s", first ? "" : " ",
					 ref_format(r->type), r->name);
				strcat(buf, rb);
				first = false;
			}
		}
		if (!buf[0]) continue;
		view_grow(view, 1);
		memmove(&view->line[i+2], &view->line[i+1],
			(view->lines - i - 2) * sizeof(struct line));
		memset(&view->line[i+1], 0, sizeof(struct line));
		view->line[i+1].type = LT_HEADER;
		{
			char *s = malloc(strlen("Refs: ") + strlen(buf) + 1);
			sprintf(s, "Refs: %s", buf);
			view->line[i+1].text = s;
		}
		i++;
	}
}

bool
open_log_view(struct view *view)
{
	char cmd[8192];
	const char *args = cmdline_args ? cmdline_args : "";
	const char *paths = file_args ? file_args : "";
	const char *logopts = opt_log_options ? opt_log_options : "";

	load_refs();
	snprintf(cmd, sizeof(cmd),
		 "git log --encoding=UTF-8 --use-mailmap --cc --stat=100 %s %s --no-color -- %s",
		 logopts, args, paths);
	if (!run_log(view, cmd)) return false;
	insert_refs_lines(view);
	return true;
}

bool
open_diff_view(struct view *view, bool force)
{
	char cmd[8192];
	const char *args = cmdline_args ? cmdline_args : "";
	const char *paths = file_args ? file_args : "";
	const char *revs = rev_args ? rev_args : "";
	const char *diffopts = opt_diff_options ? opt_diff_options : "";

	if (view->parent == views[VIEW_MAIN] && view->parent && view->parent->commit)
		revs = view->parent->commit->id;
	if (!*revs) revs = head_id;
	{
		struct io io;
		char cmd2[8192];
		(void) diffopts;
		snprintf(cmd2, sizeof(cmd2),
			 "git describe --tags %s", *revs ? revs : "HEAD");
		io.nulmode = false;
		if (io_open(&io, "%s", cmd2)) {
			char line[512];
			while (io_get(&io, line, sizeof(line))) ;
			io_status(&io);
			io_free(&io);
		}
	}
	snprintf(cmd, sizeof(cmd),
		 "git show --encoding=UTF-8 --pretty=fuller --root --patch-with-stat "
		 "--stat=100 --use-mailmap --show-notes %s --no-color --word-diff=none %s -- %s",
		 args, revs, paths);
	if (!run_log(view, cmd)) return false;
	insert_refs_lines(view);
	return true;
}

bool
open_pager_view(struct view *view)
{
	struct io io;

	clear_lines(view);
	io.nulmode = false;
	io.pipe = stdin;
	io.pid = 0;
	read_pipe_lines(view, &io, LT_DEFAULT);
	io.pipe = NULL;
	return true;
}
