static void
read_pipe_lines(struct view *view, struct io *io, int basetype)
{
	char line[8192];

	while (io_get(io, line, sizeof(line))) {
		struct line *l;
		view_grow(view, 1);
		l = &view->line[view->lines - 1];
		l->type = basetype;
		l->text = strdup(line);
