		bool first = true;

		if (!l->text || strncmp(l->text, "commit ", 7)) continue;
		{
			const char *id = l->text + 7;
			for (r = ref_list; r; r = r->next) {
				char rb[512];
				if (strncmp(r->id, id, 40)) continue;
				snprintf(rb, sizeof(rb), "%s%s%s", first ? "" : " ",
