/* ------------------------------------------------------------------ */
/* status view                                                         */
/* ------------------------------------------------------------------ */
struct statline { char *text; int kind; };  /* kind: 0=header 1=file */

static void
add_status_header(struct view *view, const char *text)
{
	view_grow(view, 1);
	{
		struct line *l = &view->line[view->lines - 1];
		memset(l, 0, sizeof(*l));
		l->type = LT_STAT_SECTION;
		l->text = strdup(text);
	}
}

static void
add_status_file(struct view *view, char status, const char *name)
{
	view_grow(view, 1);
	{
		struct line *l = &view->line[view->lines - 1];
		memset(l, 0, sizeof(*l));
		l->type = LT_STAT;
		l->stat = status;
		l->text = strdup(name);
	}
}

