/* ------------------------------------------------------------------ */
bool
open_blame_view(struct view *view, const char *file)
{
	struct io io;
	char cmd[8192];
	char rec[SIZEOF_STR];
	const char *blameopts = opt_blame_options ? opt_blame_options : "";
	const char *revs = rev_args ? rev_args : "";

	clear_lines(view);
	if (!file) {
		if (view->parent != views[VIEW_TREE])
			status_message("No file chosen, press t to open tree view");
		return false;
	}
	{
		struct io t;
		io.nulmode = true;
		if (io_open(&t, "git ls-tree -d -z HEAD -- %s", file)) {
			char l[512];
			while (io_get(&t, l, sizeof(l))) ;
			io_status(&t);
			io_free(&t);
			if (io.status == 0) {
				status_message("Cannot switch to viewing a directory");
				return false;
			}
		}
	}
	if (*revs)
		snprintf(cmd, sizeof(cmd), "git blame --encoding=UTF-8 %s %s -p -- %s",
			 blameopts, revs, file);
	else
		snprintf(cmd, sizeof(cmd), "git blame --encoding=UTF-8 %s -p -- %s",
			 blameopts, file);
	io.nulmode = false;
	if (!io_open(&io, "%s", cmd)) return false;
	while (io_get(&io, rec, sizeof(rec))) {
		struct blame_line *bl = calloc(1, sizeof(*bl));
		char *p = rec, *fields[12];
		int nf = 0;

		fields[nf++] = p;
		while (*p && nf < 12) { if (*p == 0) { fields[nf++] = p + 1; } p++; }
		if (nf < 9) { free(bl); continue; }
		/* fields: sha orig-file orig-line final-line num-lines author
		 * author-mail author-time author-tz committer ... summary? */
		strncpy(bl->id, fields[0], 40);
		bl->lineno = atoi(fields[3]);
		bl->author = strdup(fields[5]);
		if (fields[6] && strcmp(fields[6], "-"))
			bl->author_email = strdup(fields[6]);
		{
			time_t t = (time_t) strtoll(fields[7], NULL, 10);
			bl->date = t;
			bl->date_tz = strdup(fields[8] ? fields[8] : "+0000");
		}
		if (nf >= 13 && fields[12])
			bl->text = strdup(fields[12]);
		else
			bl->text = strdup("");
		view_grow(view, 1);
		view->line[view->lines - 1].type = LT_BLAME;
		view->line[view->lines - 1].blame = bl;
	}
	io_status(&io);
	io_free(&io);
	{
		char buf[512];
		if (*revs)
			snprintf(buf, sizeof(buf), "%.8s:%s", revs, file);
		else
			snprintf(buf, sizeof(buf), "%s", file);
		free(view->pos_id);
		view->pos_id = strdup(buf);
	}
	return true;
}

/* ------------------------------------------------------------------ */
/* tree view                                                           */
/* ------------------------------------------------------------------ */
bool
open_tree_view(struct view *view)
{
	struct io io;
	char rec[SIZEOF_STR];
	struct commit *head;

	clear_lines(view);
	for (head = commit_list; head; head = head->next)
		if (!strncmp(head->id, head_id, 40)) break;
	if (!head) {
		status_message("No tree exists for this commit");
		return false;
	}
	io.nulmode = true;
	if (!io_open(&io, "git ls-tree -r -l -z %s", head->id))
		return false;
	while (io_get(&io, rec, sizeof(rec))) {
		struct tree_entry *t = calloc(1, sizeof(*t));
		char *p = rec;
		char mode[16] = "", type = 'b', size[32] = "";
		char *sp;

		/* "<mode> <type> <sha>\t<size>\t<path>" */
		sp = strchr(p, ' ');
		if (!sp) { free(t); continue; }
		snprintf(mode, sizeof(mode), "%.*s", (int)(sp - p), p);
		p = sp + 1;
		type = *p;
		p += 2;
		sp = strchr(p, '\t');
		if (!sp) { free(t); continue; }
		strncpy(t->id, p, 40);
		p = sp + 1;
		sp = strchr(p, '\t');
		if (!sp) { free(t); continue; }
		snprintf(size, sizeof(size), "%.*s", (int)(sp - p), p);
		p = sp + 1;
		t->path = strdup(p);
		t->size = atol(size);
		{
			const char *slash = strrchr(p, '/');
			t->name = strdup(slash ? slash + 1 : p);
		}
		snprintf(t->mode, sizeof(t->mode), "%s", mode);
		view_grow(view, 1);
		view->line[view->lines - 1].type = LT_TREE;
		view->line[view->lines - 1].tree = t;
	}
	io_status(&io);
	io_free(&io);
	{
		struct line *l;
		view_grow(view, 1);
		memmove(&view->line[1], &view->line[0], (view->lines - 1) * sizeof(struct line));
		l = &view->line[0];
		memset(l, 0, sizeof(*l));
		l->type = LT_HEADER;
		l->text = strdup("Directory path /");
	}
	return true;
}
