{"command": "cat >> /workspace/src/view.c <<'EOF'

/* ------------------------------------------------------------------ */
/* render dispatch                                                     */
/* ------------------------------------------------------------------ */
void
render_line(struct view *view, struct line *l, struct drawbuf *b)
{
	buf_reset(b);
	switch (view->id) {
	case VIEW_MAIN:
		main_render(view, l, b);
		break;
	case VIEW_LOG:
	case VIEW_DIFF:
	case VIEW_STAGE:
	case VIEW_PAGER:
	{
		const char *text = l->text ? l->text : "";
		if (is_diffstat(text))
			render_diffstat_line(view, l, b, text);
		else
			render_text_line(view, l, b, text);
		break;
	}
	case VIEW_REFS:
	{
		attr_t dateattr = color_attr_named("refs", "date");
		attr_t authattr = color_attr_named("refs", "author");
		attr_t refattr;
		attr_t titleattr = color_attr_named("refs", "commit-title");
		attr_t defattr = color_attr("default");
		int dw, aw = 0, rw, i;
		char buf[256];

		buf_reset(b);
		if (l->type == LT_HEADER) {
			int pad = main_date_width() + 1 + main_author_width() + 1;
			buf_pad(b, pad, color_attr("cursor"));
			{
				char s[256];
				snprintf(s, sizeof(s), " %s ", l->text ? l->text : "");
				buf_addstr(b, s, color_attr("help-group"));
			}
			return;
		}
		dw = 22;
		/* compute the author width and ref width over all lines */
		for (i = 0; i < view->lines; i++) {
			struct line *l2 = &view->line[i];
			char ab[256];
			if (l2->commit) {
				author_text(ab, sizeof(ab), l2->commit->committer,
					    l2->commit->committer_email, 0);
				if ((int) strlen(ab) > aw) aw = strlen(ab);
			}
			if (l2->refname && (int) strlen(l2->refname) > rw) rw = strlen(l2->refname);
		}
		if (rw < 4) rw = 4;
		if (l->commit) {
			date_text(buf, sizeof(buf), l->commit->adate, l->commit->adate_tz,
				  l->commit->adate_tzs, view_columns[VIEW_REFS][COL_DATE].format);
			buf_addstr(b, buf, dateattr);
		}
		buf_pad(b, dw, dateattr);
		buf_addch(b, ' ', dateattr);
		if (l->commit) {
			author_text(buf, sizeof(buf), l->commit->committer,
				    l->commit->committer_email, 0);
			buf_addstr(b, buf, authattr);
		}
		buf_pad(b, aw, authattr);
		buf_addch(b, ' ', authattr);
		refattr = (l->reftype == 'b' && branch_name && l->refname &&
			   !strcmp(l->refname, branch_name))
			? color_attr("main-head") : color_attr("main-ref");
		if (l->reftype == 't') refattr = color_attr("main-tag");
		{
			char rb[512];
			snprintf(rb, sizeof(rb), "%s", l->refname ? l->refname : "");
			buf_addstr(b, rb, refattr);
			buf_pad(b, rw, refattr);
		}
		buf_addch(b, ' ', defattr);
		if (l->commit && l->commit->title)
			buf_addstr(b, l->commit->title, titleattr);
		break;
	}
	case VIEW_STATUS:
	{
		attr_t hdr = color_attr("status.header");
		attr_t st = color_attr("status.header");
		attr_t defattr = color_attr("default");

		if (l->type == LT_STAT_SECTION)
			buf_addstr(b, l->text ? l->text : "", color_attr("status.header"));
		else if (l->type == LT_STAT) {
			char s[8];
			snprintf(s, sizeof(s), "%c ", l->stat);
			buf_addstr(b, s, color_attr("status.header"));
			buf_addstr(b, l->text ? l->text : "", defattr);
		} else
			buf_addstr(b, l->text ? l->text : "", defattr);
		(void) hdr; (void) st;
		break;
	}
	case VIEW_BLAME:
	{
		struct blame_line *bl = l->blame;
		attr_t idattr = color_attr_named("blame", "id");
		attr_t authattr = color_attr_named("blame", "author");
		attr_t dateattr = color_attr_named("blame", "date");
		attr_t lineattr = color_attr_named("blame", "line-number");
		attr_t defattr = color_attr("default");
		attr_t fileattr = color_attr_named("blame", "file-name");
		int dw = 22, aw, lw, i;
		char buf[256];

		buf_reset(b);
		aw = 0; lw = 0;
		for (i = 0; i < view->lines; i++) {
			struct line *l2 = &view->line[i];
			if (!l2->blame) continue;
			if (l2->blame->author && (int) strlen(l2->blame->author) > aw)
				aw = strlen(l2->blame->author);
			{
				char n[32];
				snprintf(n, sizeof(n), "%d", l2->blame->lineno);
				if ((int) strlen(n) > lw) lw = strlen(n);
			}
		}
		if (!bl) break;
		snprintf(buf, sizeof(buf), "%.7s", bl->id);
		buf_addstr(b, buf, idattr);
		buf_pad(b, 7, idattr);
		buf_addch(b, ' ', idattr);
		buf_addstr(b, bl->author ? bl->author : "", authattr);
		buf_pad(b, aw, authattr);
		buf_addch(b, ' ', authattr);
		{
			char db[64];
			snprintf(db, sizeof(db), "%s", bl->date_tz ? bl->date_tz : "+0000");
			date_text(buf, sizeof(buf), bl->date, 0, db, NULL);
			buf_addstr(b, buf, dateattr);
		}
		buf_pad(b, dw, dateattr);
		buf_addch(b, ' ', dateattr);
		snprintf(buf, sizeof(buf), "%*d", lw, bl->lineno);
		buf_addstr(b, buf, lineattr);
		buf_addch(b, ' ', lineattr);
		buf_addch(b, graph_char(0), defattr);
		buf_addch(b, ' ', defattr);
		buf_addstr(b, bl->text ? bl->text : "", defattr);
		break;
	}
	case VIEW_TREE:
	{
		struct tree_entry *t = l->tree;
		attr_t modeattr = color_attr_named("tree", "mode");
		attr_t authattr = color_attr_named("tree", "author");
		attr_t sizeattr = color_attr_named("tree", "file-size");
		attr_t dateattr = color_attr_named("tree", "date");
		attr_t fileattr = color_attr_named("tree", "file-name");
		attr_t defattr = color_attr("default");
		int dw = 22, aw, sw, i;
