			buf_addstr(b, l->text ? l->text : "", color_attr("header"));
			return;
		}
		if (!t) break;
		aw = 0; sw = 0;
		for (i = 0; i < view->lines; i++) {
			struct line *l2 = &view->line[i];
			if (!l2->tree) continue;
			if (l2->tree->author && (int) strlen(l2->tree->author) > aw)
				aw = strlen(l2->tree->author);
			{
				char n[32];
				snprintf(n, sizeof(n), "%ld", l2->tree->size);
				if ((int) strlen(n) > sw) sw = strlen(n);
			}
		}
		buf_addstr(b, t->mode, modeattr);
		buf_pad(b, 10, modeattr);
		buf_addch(b, ' ', modeattr);
		buf_addstr(b, t->author ? t->author : "", authattr);
		buf_pad(b, aw, authattr);
		buf_addch(b, ' ', authattr);
		snprintf(buf, sizeof(buf), "%ld", t->size);
		buf_addstr(b, buf, sizeattr);
		buf_pad(b, sw, sizeattr);
		buf_addch(b, ' ', sizeattr);
		date_text(buf, sizeof(buf), t->date, 0, "+0000", NULL);
		buf_addstr(b, buf, dateattr);
		buf_pad(b, dw, dateattr);
		buf_addch(b, ' ', dateattr);
		buf_addstr(b, t->name ? t->name : "", fileattr);
		break;
	}
	case VIEW_BLOB:
	{
		attr_t defattr = color_attr("default");
		attr_t lineattr = color_attr_named("blob", "line-number");

		buf_reset(b);
		if (view_columns[VIEW_BLOB][COL_LINENO].display) {
			char buf[64];
			snprintf(buf, sizeof(buf), "%*d", 4, l->lineno);
			buf_addstr(b, buf, lineattr);
			buf_addch(b, ' ', lineattr);
		}
		buf_addstr(b, l->text ? l->text : "", defattr);
		break;
	}
	case VIEW_GREP:
	{
		attr_t fileattr = color_attr_named("grep", "file-name");
		attr_t lineattr = color_attr_named("grep", "line-number");
		attr_t defattr = color_attr("default");
		int lw = 0, i;

		buf_reset(b);
		for (i = 0; i < view->lines; i++)
			if (view->line[i].type == LT_DEFAULT) {
				char n[32];
				snprintf(n, sizeof(n), "%d", view->line[i].lineno);
				if ((int) strlen(n) > lw) lw = strlen(n);
			}
		if (l->type == LT_GREP_FILE) {
			buf_addstr(b, l->text ? l->text : "", fileattr);
			buf_addch(b, ' ', fileattr);
			return;
		}
		snprintf(buf, sizeof(buf), "%*d", lw, l->lineno);
		buf_addstr(b, buf, lineattr);
		buf_addch(b, ' ', lineattr);
		buf_addch(b, graph_char(0), defattr);
		buf_addch(b, ' ', defattr);
		buf_addstr(b, l->text ? l->text : "", defattr);
		break;
	}
	case VIEW_STASH:
		main_render(view, l, b);
		break;
	case VIEW_REFLOG:
		main_render(view, l, b);
		break;
	case VIEW_HELP:
	{
		char *keys = l->text, *act = NULL, *desc = NULL;
		attr_t keyattr = color_attr("help.header");
		attr_t actattr = color_attr("help-action");
		attr_t defattr = color_attr("default");
		char kbuf[128];

		buf_reset(b);
		if (l->type == LT_HEADER) {
			buf_addstr(b, l->text ? l->text : "", color_attr("help.header"));
			return;
		}
		if (l->type == LT_SECTION) {
			char s[256];
			snprintf(s, sizeof(s), "[%c] %s",
				 view->section_collapsed(l) ? '+' : '-', l->text ? l->text : "");
			buf_addstr(b, s, color_attr("help.header"));
			return;
		}
		if (l->type == LT_HELP_GROUP) {
			buf_addstr(b, l->text ? l->text : "", color_attr("help.group"));
			return;
		}
		if (l->text) {
			act = strchr(l->text, '\t');
			if (act) { *act = 0; act++; desc = strchr(act, '\t'); if (desc) { *desc = 0; desc++; } }
		}
		snprintf(kbuf, sizeof(kbuf), "%28s", keys ? keys : "");
		buf_addstr(b, kbuf, keyattr);
		buf_addch(b, ' ', keyattr);
		buf_addstr(b, act ? act : "", actattr);
		buf_pad(b, 28, actattr);
		buf_addstr(b, desc ? desc : "", defattr);
		break;
	}
	}
}
