/* ------------------------------------------------------------------ */
/* display drawing                                                     */
/* ------------------------------------------------------------------ */
int view_height[2];

void
resize_display(void)
{
	int total = LINES - 1;
	int i;

	if (display_size == 1) {
		view_height[0] = total;
		if (display[0]) {
			display[0]->height = total - 1;
		}
	} else {
		int child = (int) (0.67 * total);
		if (child < 4) child = 4;
		if (child > total - 4) child = total - 4;
		view_height[1] = child;
		view_height[0] = total - child;
		if (display[0]) display[0]->height = view_height[0] - 1;
		if (display[1]) display[1]->height = view_height[1] - 1;
	}
	for (i = 0; i < display_size; i++) {
		if (!display[i]) continue;
		if (display[i]->win) { delwin(display[i]->win); display[i]->win = NULL; }
	}
}

void
draw_view(struct view *view)
{
	int row;
	int w = COLS;
	struct drawbuf buf;
	attr_t cursorattr;
	bool focused = (display[current_view] == view);
	int rowbase = 0;

	for (row = 0; row < display_size; row++)
		if (display[row] == view) { rowbase = (row == 0) ? 0 : view_height[0]; break; }
	if (!view->win) {
		int h = (view->id == display[display_size-1]->id) ? view_height[display_size-1] : view_height[0];
		view->win = newwin(h, w, rowbase, 0);
	}
	cursorattr = color_attr(focused ? "cursor" : "cursor-blur");
	for (row = 0; row < view->height; row++) {
		int idx = view->offset + row;
		struct line *l;
		bool selected;

		wmove(view->win, row, 0);
		if (idx >= view->lines) break;
		l = &view->line[idx];
		selected = (idx == view->lineno);
		render_line(view, l, &buf);
		/* draw with horizontal scroll */
		{
			int i, x = 0;
			attr_t cur = 0;
			bool started = false;
			for (i = 0; i < buf.len; i++) {
				int col = i - view->col_offset;
				if (col < 0 || col >= w) continue;
				wmove(view->win, row, col);
				if (!started || buf.attrs[i] != cur) {
					wattroff(view->win, cur);
					wattron(view->win, selected ? cursorattr : buf.attrs[i]);
					cur = selected ? cursorattr : buf.attrs[i];
					started = true;
				}
				waddch(view->win, buf.cells[i]);
			}
			/* fill the rest of the row */
			{
				attr_t fill = selected ? cursorattr : color_attr("default");
				wattron(view->win, fill);
				for (; x < w; x++) {
					int col = x;
					wmove(view->win, row, col);
					waddch(view->win, ' ');
				}
				wattroff(view->win, fill);
			}
		}
	}
	/* erase the remaining rows */
	for (; row < view->height; row++) {
		wmove(view->win, row, 0);
		wclrtoeol(view->win);
	}
	update_title(view);
}

void
update_title(struct view *view)
{
	char buf[2048];
	attr_t tattr;
	int rowbase = 0, i;
	bool focused = (display[current_view] == view);

	for (i = 0; i < display_size; i++)
		if (display[i] == view) { rowbase = (i == 0) ? 0 : view_height[0]; break; }
	render_title(view, buf, sizeof(buf));
	tattr = color_attr(focused ? "title-focus" : "title-blur");
	{
		int trow = rowbase + view->height;
		int w = COLS;
		int len = strlen(buf);
		int percent = 0;

		if (view->lines)
			percent = (view->offset + view->height) * 100 / view->lines;
		if (percent > 100) percent = 100;
		wbkgdset(view->win, color_attr_pair("title-focus", NULL, NULL) & A_COLOR);
		mvwhline(view->win, trow, 0, ' ', w);
		wattron(view->win, tattr);
		mvwaddstr(view->win, trow, 0, buf);
		wattroff(view->win, tattr);
		{
			char pbuf[8];
			snprintf(pbuf, sizeof(pbuf), "%3d%%", percent);
			wattron(view->win, tattr);
			mvwaddstr(view->win, trow, w - strlen(pbuf), pbuf);
			wattroff(view->win, tattr);
		}
	}
}

void
draw_status(void)
{
	int row = LINES - 1;
	const char *text;

	(void) text;
	wmove(stdscr, row, 0);
	wclrtoeol(stdscr);
	if (prompt_active) {
		char buf[4096];
		snprintf(buf, sizeof(buf), "%s%s", prompt_text ? prompt_text : "",
			 prompt_buf ? prompt_buf : "");
		wattron(stdscr, color_attr("status"));
		mvwaddstr(stdscr, row, 0, buf);
		wattroff(stdscr, color_attr("status"));
	} else if (status_msg) {
		wattron(stdscr, color_attr("status"));
		mvwaddstr(stdscr, row, 0, status_msg);
		wattroff(stdscr, color_attr("status"));
	}
}

void
draw_display(void)
{
	int i;

	erase();
	resize_display();
	for (i = 0; i < display_size; i++)
		if (display[i]) draw_view(display[i]);
	draw_status();
	refresh();
}
EOF
echo ok"}

