#include "view.h"
#include "graph.h"
#include "draw.h"
#include "io.h"
#include "config.h"
#include <locale.h>
#include <signal.h>
#include <termios.h>

static void usage(void)
{
	printf("tig %s \n\n", TIG_VERSION);
	printf("Usage: tig        [options] [revs] [--] [paths]\n");
	printf("   or: tig log    [options] [revs] [--] [paths]\n");
	printf("   or: tig show   [options] [revs] [--] [paths]\n");
	printf("   or: tig reflog [options] [revs]\n");
	printf("   or: tig blame  [options] [rev] [--] path\n");
	printf("   or: tig grep   [options] [pattern]\n");
	printf("   or: tig refs   [options]\n");
	printf("   or: tig stash  [options]\n");
	printf("   or: tig status\n");
	printf("   or: tig <      [git command output]\n");
	printf("\nOptions:\n");
	printf("  +<number>       Select line <number> in the first view\n");
	printf("  -v, --version   Show version and exit\n");
	printf("  -h, --help      Show help message and exit\n");
	printf("  -C <path>       Start in <path>\n");
}

static void print_version(void)
{
	const char *cv = curses_version();
	const char *v = cv && !strncmp(cv, "ncurses ", 8) ? cv + 8 : cv;

	printf("tig version %s\n", TIG_VERSION);
	printf("ncursesw version %s\n", v ? v : "");
}

/* classify command line args with git rev-parse */
static void
classify_args(char **argv, int argc)
{
	char cmd[8192];
	char buf[65536];
	int i;
	size_t n = 0;

	buf[0] = 0;
	for (i = 0; i < argc; i++) {
		if (n) buf[n++] = ' ';
		n += snprintf(buf + n, sizeof(buf) - n, "%s", argv[i]);
	}
	/* paths */
	snprintf(cmd, sizeof(cmd), "git rev-parse --no-revs --no-flags %s", buf);
	if (!capture_output(file_buf_, sizeof(file_buf_), "%s", cmd))
		die("No revisions match the given arguments.");
	free(file_args);
	file_args = strdup(chomp(file_buf_));
	/* flags */
	snprintf(cmd, sizeof(cmd), "git rev-parse --flags --no-revs %s", buf);
	if (!capture_output(flags_buf_, sizeof(flags_buf_), "%s", cmd))
		die("No revisions match the given arguments.");
	/* revs */
	snprintf(cmd, sizeof(cmd), "git rev-parse --symbolic --revs-only %s", buf);
	capture_output(revs_buf_, sizeof(revs_buf_), "%s", cmd);
	/* combine flags and revs in order: flags then revs */
	{
		size_t fl = strlen(chomp(flags_buf_));
		size_t rv = strlen(chomp(revs_buf_));
		char *all = malloc(fl + rv + 3);
		all[0] = 0;
		if (fl) { strcat(all, flags_buf_); strcat(all, " "); }
		if (rv) strcat(all, revs_buf_);
		free(cmdline_args);
		cmdline_args = strdup(chomp(all));
		free(rev_args); rev_args = strdup(chomp(revs_buf_));
		free(all);
	}
}

int
main(int argc, const char *argv[])
{
	const char *tigrc_system = getenv("TIGRC_SYSTEM");
	const char *tigrc_user = getenv("TIGRC_USER");
	const char *trace = getenv("TIG_TRACE");
	const char *script = getenv("TIG_SCRIPT");
	const char *editor;
	const char *cwd = NULL;
	char start_line[32] = "";
	int i, view = VIEW_MAIN;
	bool pager = false;
	char *pager_input = NULL;
	const char *subcmd = NULL;

	trace_file = trace;
	/* parse command line */
	for (i = 1; i < argc; i++) {
		const char *a = argv[i];
		if (a[0] == '+') { snprintf(start_line, sizeof(start_line), "%s", a + 1); continue; }
		if (!strcmp(a, "-v") || !strcmp(a, "--version")) { print_version(); return 0; }
		if (!strcmp(a, "-h") || !strcmp(a, "--help")) { usage(); return 0; }
		if (!strcmp(a, "-C") && i + 1 < argc) { cwd = argv[++i]; continue; }
		if (!strcmp(a, "--")) { i++; break; }
		if (a[0] != '-' && !subcmd) {
			/* subcommand? */
			if (!strcmp(a, "log") || !strcmp(a, "show") || !strcmp(a, "reflog") ||
			    !strcmp(a, "blame") || !strcmp(a, "grep") || !strcmp(a, "refs") ||
			    !strcmp(a, "stash") || !strcmp(a, "status")) {
				subcmd = a;
				continue;
			}
			break;
		}
		break;
	}
	{
		char *rest[512];
		int nrest = 0;
		for (; i < argc && nrest < 511; i++)
			rest[nrest++] = (char *) argv[i];
		rest[nrest] = NULL;
		if (nrest)
			classify_args(rest, nrest);
	}
	if (cwd && chdir(cwd) < 0)
		die("Failed to chdir(%s): %s", cwd, strerror(errno));
	/* repo info */
	{
		char buf[4096];
		if (!capture_output(buf, sizeof(buf),
				    "git rev-parse --git-dir --is-inside-work-tree "
				    "--show-cdup --show-prefix HEAD --symbolic-full-name HEAD")) {
			load_git_config();
			die("Not a git repository");
		}
	}
	load_git_config();
	/* line graphics */
	if (opt_line_graphics == -1) {
		const char *loc = setlocale(LC_ALL, "");
		opt_line_graphics = (loc && (strstr(loc, "UTF") || strstr(loc, "utf"))) ? 2 : 0;
	}
	/* editor */
	editor = getenv("TIG_EDITOR");
	if (!editor || !*editor) editor = getenv("GIT_EDITOR");
	if (!editor || !*editor) editor = getenv("VISUAL");
	if (!editor || !*editor) editor = getenv("EDITOR");
	if (editor && *editor) { free(opt_editor); opt_editor = strdup(editor); }
	/* config */
	if (tigrc_user && *tigrc_user) {
		read_config(tigrc_user, false, false);
	} else {
		char path[4096];
		const char *xdg = getenv("XDG_CONFIG_HOME");
		struct stat st;
		if (xdg && *xdg)
			snprintf(path, sizeof(path), "%s/tig/config", xdg);
		else {
			const char *home = getenv("HOME");
			snprintf(path, sizeof(path), "%s/.config/tig/config", home ? home : "");
			if (stat(path, &st) < 0)
				snprintf(path, sizeof(path), "%s/.tigrc", home ? home : "");
		}
		if (stat(path, &st) == 0)
			read_config(path, false, false);
	}
	if (tigrc_system) {
		if (*tigrc_system) read_config(tigrc_system, false, false);
	} else {
		struct stat st;
		if (stat("/etc/tigrc", &st) == 0)
			read_config("/etc/tigrc", false, false);
	}
	/* pager mode: stdin is not a tty */
	if (!isatty(0)) {
		pager = true;
	}
	if (!isatty(1))
		die("Failed to open tty for input");
	/* ncurses */
	{
		const char *term = getenv("TERM");
		if (term && !strcmp(term, "unknown")) setenv("TERM", "xterm", 1);
		if (!getenv("TERM")) die("TERM environment variable not set");
		if (!newterm(getenv("TERM"), stdout, stdin))
			die("Failed to initialize curses");
	}
	{
		const char *nod = getenv("TIG_NO_DISPLAY");
		if (nod) {
			FILE *n = fopen("/dev/null", "w");
			if (n) { freopen("/dev/null", "w", stdout); fclose(n); }
		}
	}
	raw();
	noecho();
	nonl();
	intrflush(stdscr, FALSE);
	keypad(stdscr, TRUE);
	curs_set(0);
	draw_init();
	load_default_bindings();
	refresh();
	/* initial view */
	if (pager) {
		pager_mode = true;
		view_open_driver(VIEW_PAGER, NULL);
	} else if (subcmd) {
		if (!strcmp(subcmd, "log")) view = VIEW_LOG;
		else if (!strcmp(subcmd, "show")) view = VIEW_DIFF;
		else if (!strcmp(subcmd, "reflog")) view = VIEW_REFLOG;
		else if (!strcmp(subcmd, "blame")) view = VIEW_BLAME;
		else if (!strcmp(subcmd, "grep")) view = VIEW_GREP;
		else if (!strcmp(subcmd, "refs")) view = VIEW_REFS;
		else if (!strcmp(subcmd, "stash")) view = VIEW_STASH;
		else if (!strcmp(subcmd, "status")) view = VIEW_STATUS;
		view_open_driver(view, NULL);
	} else {
		view_open_driver(VIEW_MAIN, NULL);
	}
	if (!views[view] || views[view]->lines == 0) {
		if (view == VIEW_BLAME)
			die("Invalid number of options to blame");
	}
	draw_display();
	/* main loop */
	for (;;) {
		int key = getch();
		if (key == ERR) continue;
		if (handle_key(key)) break;
		draw_display();
	}
	endwin();
	return 0;
}
EOF
echo ok"}

