#include "view.h"
#include "config.h"
#include "draw.h"
#include "io.h"

/* handle one key; returns true to quit */
bool
handle_key(int key)
{
	const char *req;
	struct view *v = display[current_view];
	int map = KM_GENERIC;

	if (prompt_active) { prompt_handle_key(key); return false; }
	if (option_menu_active) {
		switch (key) {
		case 'q': option_menu_active = false; status_msg = NULL; return false;
		case KEY_RIGHT: case KEY_DOWN: option_menu_next(1); return false;
		case KEY_LEFT: case KEY_UP: option_menu_next(-1); return false;
		case '\n': case 13: option_menu_toggle(); return false;
		}
		req = binding_get(KM_TOGGLE, key);
		if (req) {
			if (!strncmp(req, ":toggle ", 8))
				toggle_option(req + 8, NULL);
			option_menu_active = false;
			return false;
		}
		req = binding_get(KM_GENERIC, key);
		if (req && !strcmp(req, "options")) { option_menu_next(1); return false; }
		return false;
	}
	if ((req = binding_get(KM_TOGGLE, key)) && v && v->id == VIEW_MAIN) {
		/* 'o' prefix handled below */
	}
	if (key == 'o') {
		option_menu_active = true;
		option_menu_index = 0;
		show_status_line();
		return false;
	}
	if (v) map = (v->id == VIEW_MAIN) ? KM_MAIN : KM_GENERIC;
	req = v ? binding_get(view_keymap(v->id), key) : NULL;
	if (!req) req = binding_get(KM_GENERIC, key);
	if (!req) {
		status_message("Unknown key, press h for help");
		return false;
	}
	return exec_request(req);
}

int
view_keymap(int id)
{
	switch (id) {
	case VIEW_DIFF: return KM_DIFF;
	case VIEW_REFLOG: return KM_REFLOG;
	case VIEW_REFS: return KM_REFS;
	case VIEW_STATUS: return KM_STATUS;
	case VIEW_STAGE: return KM_STAGE;
	case VIEW_STASH: return KM_STASH;
	case VIEW_PAGER: return KM_PAGER;
	case VIEW_HELP: return KM_HELP;
	}
	return KM_GENERIC;
}

/* execute a request string; returns true to quit */
bool
exec_request(const char *req)
{
	struct view *v = display[current_view];

	if (*req == '?') { external_cmd(req + 1); return false; }
	if (*req == '!') { char buf[8192]; snprintf(buf, sizeof(buf), "%s", req + 1);
		expand_vars(buf, sizeof(buf)); system_run("%s", buf); view_reload(v); return false; }
	if (*req == ':') { run_prompt_command(req + 1); return false; }
	if (!strcmp(req, "quit")) return true;
	if (!strcmp(req, "view-close")) { view_close(v); return false; }
	if (!strcmp(req, "view-main")) view_open_driver(VIEW_MAIN, NULL);
	else if (!strcmp(req, "view-diff")) view_open_driver(VIEW_DIFF, v);
	else if (!strcmp(req, "view-log")) view_open_driver(VIEW_LOG, NULL);
	else if (!strcmp(req, "view-reflog")) view_open_driver(VIEW_REFLOG, NULL);
	else if (!strcmp(req, "view-tree")) view_open_driver(VIEW_TREE, v);
	else if (!strcmp(req, "view-blob")) view_open_driver(VIEW_BLOB, v);
	else if (!strcmp(req, "view-blame")) view_open_driver(VIEW_BLAME, v);
	else if (!strcmp(req, "view-refs")) view_open_driver(VIEW_REFS, NULL);
	else if (!strcmp(req, "view-status")) view_open_driver(VIEW_STATUS, NULL);
	else if (!strcmp(req, "view-stage")) view_open_driver(VIEW_STAGE, NULL);
	else if (!strcmp(req, "view-stash")) view_open_driver(VIEW_STASH, NULL);
	else if (!strcmp(req, "view-grep")) view_open_driver(VIEW_GREP, NULL);
	else if (!strcmp(req, "view-pager")) view_open_driver(VIEW_PAGER, NULL);
	else if (!strcmp(req, "view-help")) view_open_driver(VIEW_HELP, NULL);
	else if (!strcmp(req, "view-next")) view_next();
	else if (!strcmp(req, "back")) view_back();
	else if (!strcmp(req, "next")) view_move_next(v);
	else if (!strcmp(req, "previous")) view_move_prev(v);
	else if (!strcmp(req, "parent")) view_parent(v);
	else if (!strcmp(req, "refresh")) view_reload(v);
	else if (!strcmp(req, "maximize")) { display[0] = v; display_size = 1; current_view = 0; }
	else if (!strcmp(req, "enter")) view_enter(v);
	else if (!strcmp(req, "move-up")) move_cursor(v, REQ_MOVE_UP);
	else if (!strcmp(req, "move-down")) move_cursor(v, REQ_MOVE_DOWN);
	else if (!strcmp(req, "move-page-up")) move_cursor(v, REQ_MOVE_PAGE_UP);
	else if (!strcmp(req, "move-page-down")) move_cursor(v, REQ_MOVE_PAGE_DOWN);
	else if (!strcmp(req, "move-half-page-up")) move_cursor(v, REQ_MOVE_HALF_PAGE_UP);
	else if (!strcmp(req, "move-half-page-down")) move_cursor(v, REQ_MOVE_HALF_PAGE_DOWN);
	else if (!strcmp(req, "move-first-line")) move_cursor(v, REQ_MOVE_FIRST_LINE);
	else if (!strcmp(req, "move-last-line")) move_cursor(v, REQ_MOVE_LAST_LINE);
	else if (!strcmp(req, "scroll-line-up")) scroll_view(v, REQ_SCROLL_LINE_UP);
	else if (!strcmp(req, "scroll-line-down")) scroll_view(v, REQ_SCROLL_LINE_DOWN);
	else if (!strcmp(req, "scroll-page-up")) scroll_view(v, REQ_SCROLL_PAGE_UP);
	else if (!strcmp(req, "scroll-page-down")) scroll_view(v, REQ_SCROLL_PAGE_DOWN);
	else if (!strcmp(req, "scroll-first-col")) scroll_view(v, REQ_SCROLL_FIRST_COL);
	else if (!strcmp(req, "scroll-left")) scroll_view(v, REQ_SCROLL_LEFT);
	else if (!strcmp(req, "scroll-right")) scroll_view(v, REQ_SCROLL_RIGHT);
	else if (!strcmp(req, "search")) prompt_open("Search: ", search_pattern ? search_pattern : "", false);
	else if (!strcmp(req, "search-back")) prompt_open("Search: ", search_pattern ? search_pattern : "", false);
	else if (!strcmp(req, "find-next")) find_next(v, false);
	else if (!strcmp(req, "find-prev")) find_next(v, true);
	else if (!strcmp(req, "prompt")) prompt_open(":", "", false);
	else if (!strcmp(req, "edit")) open_editor(NULL);
	else if (!strcmp(req, "options")) { option_menu_active = true; option_menu_index = 0; show_status_line(); }
	else if (!strcmp(req, "screen-redraw")) clear(); redrawwin(stdscr);
	else if (!strcmp(req, "stop-loading")) { }
	else if (!strcmp(req, "show-version")) status_message("tig version " TIG_VERSION);
	else if (!strcmp(req, "none")) { }
	else if (!strcmp(req, "status-update")) status_message("Nothing to update");
	else if (!strcmp(req, "status-revert")) status_message("Nothing to revert");
	else if (!strcmp(req, "status-merge")) status_message("No file to merge");
	else if (!strcmp(req, "stage-update-line")) status_message("Nothing to stage");
	else if (!strcmp(req, "stage-update-part")) status_message("Nothing to stage");
	else if (!strcmp(req, "stage-split-chunk")) status_message("No chunk to split");
	else return false;
	return false;
}
